            if (ch.SubscriberCount != 3) return "SubscriberCount 기대 3, 결과 " + ch.SubscriberCount;
            log.Clear(); ch.Publish(2);
            return Expect(log, "A2 B2 N2", "다음 Publish 부터는 맨 뒤 순서로 호출");
