            if (input.GetBinding("J") != "dash") return "실패한 Bind 가 기존 바인딩을 지움";
            input.Press("J"); input.AdvanceFrame(s);
            if (s.X != 3 || s.EnemyHp != 1000) return "J 는 dash 로 바뀌었는데 결과가 다름: " + s.Snapshot();
            if (!input.Unbind("K") || input.Unbind("K")) return "Unbind 반환값이 틀림 (첫 번째 true, 두 번째 false)";
            if (input.GetBinding("K") != null || input.Press("K")) return "Unbind 한 키가 여전히 동작";
            if (input.GetBinding("없는키") != null) return "바인딩 없는 키의 GetBinding 이 null 이 아님";
            return null;
        });

        Run("record-frames", () =>
        {
            var input = NewInput(); var s = new GameState(1);
            input.Bind("W", "up"); input.Bind("J", "attack");
            input.Press("W"); input.Press("J"); input.AdvanceFrame(s);
            input.AdvanceFrame(s);
            input.Press("Q"); input.AdvanceFrame(s);
            input.Press("J"); input.Press("W"); input.Press("W"); input.AdvanceFrame(s);
            string got = Rec(input.Recording);
            return got == "0:up 0:attack 3:attack 3:up 3:up" ? null
                : "기록 (프레임:id) 기대 [0:up 0:attack 3:attack 3:up 3:up], 결과 [" + got + "]";
        });

        Run("replay-identical", () =>
        {
            var input = NewInput(); var s = new GameState(12345);
            input.Bind("J", "attack"); input.Bind("D", "right"); input.Bind("Shift", "dash");
            for (int f = 0; f < 40; f++)
            {
                if (f % 2 == 0) input.Press("J");
                if (f % 5 == 0) input.Press("D");
                if (f == 7 || f == 8 || f == 30) input.Press("Shift");
                if (f == 9) { input.Press("J"); input.Press("J"); }
                input.AdvanceFrame(s);
            }
            for (int f = 0; f < 6; f++) input.AdvanceFrame(s);
            var fresh = new GameState(12345);
            input.Replay(fresh, input.Recording, s.Frame);
            if (fresh.Snapshot() != s.Snapshot()) return "리플레이 결과가 라이브와 다름. 라이브 " + s.Snapshot() + ", 리플레이 " + fresh.Snapshot();
            if (s.EnemyHp == 1000) return "테스트 전제 오류: 공격이 한 번도 적용되지 않음";
            return null;
        });

        Run("replay-after-rebind", () =>
        {
            var input = NewInput(); var s = new GameState(99);
            input.Bind("J", "attack"); input.Bind("K", "dash");
            for (int f = 0; f < 30; f++)
            {
                if (f == 10) { input.Bind("J", "dash"); input.Bind("K", "attack"); }
                if (f == 20) { input.Unbind("K"); input.Bind("L", "rest"); }
                if (f % 3 == 0) input.Press("J");
                if (f % 4 == 1) input.Press("K");
                if (f % 2 == 0) input.Press("L");
                input.AdvanceFrame(s);
            }
            input.Unbind("J"); input.Unbind("L"); input.Bind("J", "up");
            var fresh = new GameState(99);
            input.Replay(fresh, input.Recording, s.Frame);
            return fresh.Snapshot() == s.Snapshot() ? null
                : "녹화 도중과 이후에 키를 다시 묶었더니 리플레이가 달라짐 (키가 아니라 커맨드를 기록해야 함). 라이브 " + s.Snapshot() + ", 리플레이 " + fresh.Snapshot();
        });

        Run("replay-is-pure", () =>
        {
            var input = NewInput(); var s = new GameState(5);
            input.Bind("J", "attack"); input.Bind("W", "up");
            for (int f = 0; f < 12; f++) { if (f % 4 == 0) input.Press("J"); input.Press("W"); input.AdvanceFrame(s); }
            int count = input.Recording.Count;
            string before = Rec(input.Recording);
            input.Press("W");
            var a = new GameState(5); input.Replay(a, input.Recording, s.Frame);
            var b = new GameState(5); input.Replay(b, input.Recording, s.Frame);
            if (input.Recording.Count != count || Rec(input.Recording) != before) return "Replay 가 Recording 을 변경함 (" + count + "개 -> " + input.Recording.Count + "개)";
            if (a.Snapshot() != s.Snapshot() || b.Snapshot() != s.Snapshot()) return "같은 스트림을 두 번 재생한 결과가 라이브와 다름: " + a.Snapshot() + " / " + b.Snapshot() + " / 라이브 " + s.Snapshot();
            if (input.GetBinding("J") != "attack") return "Replay 가 바인딩을 변경함";
            int y = s.Y; input.AdvanceFrame(s);
            if (s.Y != y + 1) return "Replay 가 라이브 입력 버퍼를 건드림 (Replay 전에 누른 W 가 사라지거나 중복 실행됨)";
            var other = NewInput();
            var c = new GameState(5); other.Replay(c, input.Recording, 12);
            var d = new GameState(5); input.Replay(d, input.Recording, 12);
            return c.Snapshot() == d.Snapshot() ? null : "바인딩이 하나도 없는 다른 CommandInput 으로 재생한 결과가 다름: " + c.Snapshot() + " vs " + d.Snapshot();
        });

        Run("invalid-input", () =>
        {
            var input = NewInput();
            try { input.Register(new Cmd("attack", s => { })); return "같은 id 를 두 번 Register 해도 ArgumentException 이 없음"; }
            catch (System.ArgumentException) { }
            try { input.Register(null); return "Register(null) 이 ArgumentNullException 을 던지지 않음"; }
            catch (System.ArgumentNullException) { }
            var stream = new System.Collections.Generic.List<RecordedCommand>
            {
                new RecordedCommand(0, "right"), new RecordedCommand(1, "teleport"), new RecordedCommand(2, "right")
            };
            var fresh = new GameState(3);
            try { input.Replay(fresh, stream, 5); return "등록되지 않은 id 가 든 스트림을 재생해도 InvalidOperationException 이 없음"; }
            catch (System.InvalidOperationException) { }
            return fresh.Snapshot() == new GameState(3).Snapshot() ? null : "예외 전에 상태가 일부 바뀜: " + fresh.Snapshot();
        });

        Run("press-time-binding", () =>
        {
            var input = NewInput(); var s = new GameState(7);
            input.Bind("J", "dash"); input.Bind("K", "up");
            input.Press("J"); input.Press("K");
            input.Bind("J", "up"); input.Unbind("K");      // 누른 뒤, AdvanceFrame 전에 바인딩을 바꾼다
            input.AdvanceFrame(s);
            if (s.X != 3 || s.Y != 1) return "Press 시점의 바인딩(J = dash, K = up)으로 실행되어야 함. 기대 P(3,1), 결과 " + s.Snapshot();
            string got = Rec(input.Recording);
            return got == "0:dash 0:up" ? null : "기록 기대 [0:dash 0:up], 결과 [" + got + "]";
        });

        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(31337);
            string[] keys = { "A", "B", "C", "D", "E", "F" };
            for (int round = 0; round < 60; round++)
            {
                uint seed = (uint)rng.Next(1, 1000000);
                var input = NewInput(); var live = new GameState(seed); var reference = new GameState(seed);
                var map = new System.Collections.Generic.Dictionary<string, string>();
                int frames = rng.Next(1, 120);
                for (int f = 0; f < frames; f++)
                {
                    if (rng.Next(100) < 25)
                    {
                        string k = keys[rng.Next(keys.Length)];
                        if (rng.Next(4) == 0) { input.Unbind(k); map.Remove(k); }
                        else { string id = Ids[rng.Next(Ids.Length)]; input.Bind(k, id); map[k] = id; }
                    }
                    int presses = rng.Next(0, 4);
                    for (int p = 0; p < presses; p++)
                    {
                        string k = keys[rng.Next(keys.Length)];
                        bool ok = input.Press(k);
                        if (ok != map.ContainsKey(k)) return "라운드 " + round + ": Press(" + k + ") 반환값 기대 " + map.ContainsKey(k) + ", 결과 " + ok;
                        if (ok) Apply(map[k], reference);
                    }
                    input.AdvanceFrame(live);
                    reference.Tick();
                    if (live.Snapshot() != reference.Snapshot()) return "라운드 " + round + ", 프레임 " + f + ": 라이브 상태 기대 " + reference.Snapshot() + ", 결과 " + live.Snapshot();
                }
                var fresh = new GameState(seed);
                input.Replay(fresh, input.Recording, frames);
                if (fresh.Snapshot() != reference.Snapshot()) return "라운드 " + round + " (" + frames + "프레임, 커맨드 " + input.Recording.Count + "개): 리플레이 기대 " + reference.Snapshot() + ", 결과 " + fresh.Snapshot();
            }
            return null;
        });
    }
}

