using System;
using System.Collections.Generic;

public class Enemy
{
    public string Name { get; }
    public int MaxHp { get; }
    public int Hp { get; protected set; }
    public int Speed { get; }
    public int X { get; protected set; }
    public bool IsDead { get { return Hp == 0; } }

    public Enemy(string name, int maxHp, int speed)
    {
        Name = name; MaxHp = maxHp; Hp = maxHp; Speed = speed;
    }

    // 계약: steps >= 0 이면 예외 없이 X 가 정확히 steps * Speed 만큼 늘어난다.
    public virtual void Walk(int steps)
    {
        X += steps * Speed;
    }

    // 계약: amount < 0 이면 ArgumentOutOfRangeException.
    //       반환값은 이 호출로 실제 줄어든 Hp 이고, Hp 는 0 아래로 내려가지 않는다.
    public virtual int TakeDamage(int amount)
    {
        if (amount < 0) throw new ArgumentOutOfRangeException(nameof(amount));
        int dealt = Math.Min(Hp, amount);
        Hp -= dealt;
        return dealt;
    }

    // 계약: TakeDamage(amount) 를 hits 번 호출한 것과 결과가 같다. 반환값은 그 반환값들의 합.
    public virtual int TakeBurst(int hits, int amount)
    {
        int total = 0;
        for (int i = 0; i < hits; i++) total += TakeDamage(amount);
        return total;
    }
}

// 박쥐, 와이번: 땅에 닿지 않고 고도를 유지한 채 이동한다.
public class FlyingEnemy : Enemy
{
    public int Altitude { get; private set; }

    public FlyingEnemy(string name, int maxHp, int speed, int altitude) : base(name, maxHp, speed)
    {
        Altitude = altitude;
    }

    // Walk 를 재정의하지 않는다: 기반 클래스의 계약(예외 없이 steps * Speed 만큼 전진)을 그대로 지킨다.
    // 기존 호출부를 위해 Fly 는 남기되 같은 동작에 위임한다.
    public void Fly(int steps)
    {
        Walk(steps);
    }
}

// 보호막이 남아 있는 동안에는 보호막이 피해를 먼저 흡수한다.
public class ShieldedEnemy : Enemy
{
    public int Shield { get; private set; }

    public ShieldedEnemy(string name, int maxHp, int speed, int shield) : base(name, maxHp, speed)
    {
        Shield = shield;
    }

    public override int TakeDamage(int amount)
    {
        if (amount < 0) throw new ArgumentOutOfRangeException(nameof(amount));
        int absorbed = Math.Min(Shield, amount);
        Shield -= absorbed;
        // 반환값의 계약은 "실제 줄어든 Hp"다. 보호막이 흡수한 양은 포함하지 않는다.
        return base.TakeDamage(amount - absorbed);
    }
}

// 타격 한 번마다 Armor 만큼 피해를 깎는다.
public class ArmoredEnemy : Enemy
{
    public int Armor { get; }

    public ArmoredEnemy(string name, int maxHp, int speed, int armor) : base(name, maxHp, speed)
    {
        Armor = armor;
    }

    public override int TakeDamage(int amount)
    {
        if (amount < 0) throw new ArgumentOutOfRangeException(nameof(amount));
        return base.TakeDamage(Math.Max(0, amount - Armor));
    }

    // TakeBurst 는 재정의하지 않는다. 기반 구현이 타격마다 (재정의된) TakeDamage 를 부르므로
    // 방어력은 거기서 한 번만 적용된다.
}

// Enemy 만 알고 쓰는 쪽. 이 클래스에는 버그가 없습니다.
public static class Encounter
{
    // 순찰 틱: 살아 있는 적을 모두 steps 만큼 전진시킨다.
    public static void AdvanceAll(List<Enemy> enemies, int steps)
    {
        for (int i = 0; i < enemies.Count; i++)
        {
            if (!enemies[i].IsDead) enemies[i].Walk(steps);
        }
    }

    // 광역 연타: 모든 적에게 amount 짜리 타격을 hits 번. 반환값(실제로 깎은 Hp 의 합)은 흡혈 회복량이 된다.
    public static int BurstAll(List<Enemy> enemies, int hits, int amount)
    {
        int total = 0;
        for (int i = 0; i < enemies.Count; i++) total += enemies[i].TakeBurst(hits, amount);
        return total;
    }
}

