public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static string Thrown(System.Action a)
    {
        try { a(); } catch (System.Exception ex) { return ex.GetType().Name; }
        return "없음";
    }

    // 참조 모델: 종류별 규칙을 한곳에 풀어 쓴 계산기 (kind 0 일반, 1 비행, 2 보호막, 3 중갑)
    sealed class Model
    {
        public int Kind, Hp, Speed, X, Shield, Armor;
        public int Damage(int amount)
        {
            int through = amount;
            if (Kind == 2) { int absorbed = System.Math.Min(Shield, amount); Shield -= absorbed; through = amount - absorbed; }
            if (Kind == 3) through = System.Math.Max(0, amount - Armor);
            int dealt = System.Math.Min(Hp, through);
            Hp -= dealt;
            return dealt;
        }
        public int Burst(int hits, int amount) { int t = 0; for (int i = 0; i < hits; i++) t += Damage(amount); return t; }
    }

    static Enemy Make(Model m)
    {
        switch (m.Kind)
        {
            case 1: return new FlyingEnemy("bat", m.Hp, m.Speed, 7);
            case 2: return new ShieldedEnemy("mage", m.Hp, m.Speed, m.Shield);
            case 3: return new ArmoredEnemy("knight", m.Hp, m.Speed, m.Armor);
            default: return new Enemy("grunt", m.Hp, m.Speed);
        }
    }

    public static void Main()
    {
        Run("flying-walk-contract", () =>
        {
            var bat = new FlyingEnemy("bat", 20, 3, 7);
            Enemy asBase = bat;
            string t = Thrown(() => asBase.Walk(4));
            if (t != "없음") return "Enemy 참조로 FlyingEnemy.Walk(4) 호출: 예외가 없어야 하는데 " + t;
