        });

        Run("burst-all-lifesteal-total", () =>
        {
            var list = new System.Collections.Generic.List<Enemy> { new ShieldedEnemy("mage", 50, 1, 20), new Enemy("grunt", 30, 1) };
            int total = Encounter.BurstAll(list, 2, 15);
            if (total != 40) return "BurstAll(2타 x 15) 대상 [보호막 20 / Hp 50, 일반 Hp 30]: 실제로 깎인 Hp 는 10 + 30 = 40 인데 반환 " + total;
            return list[0].Hp == 40 && list[1].Hp == 0 ? null : "Hp 기대 40, 0. 결과 " + list[0].Hp + ", " + list[1].Hp;
        });

        Run("armored-burst-equals-single-hits", () =>
        {
