            int a = burst.TakeBurst(3, 20);
            int b = single.TakeDamage(20) + single.TakeDamage(20) + single.TakeDamage(20);
            if (b != 45 || single.Hp != 55) return "방어 5 에 TakeDamage(20) 세 번: 기대 합 45 / Hp 55, 결과 " + b + " / " + single.Hp;
            if (a != 45 || burst.Hp != 55) return "방어 5 에 TakeBurst(3, 20): TakeDamage(20) 세 번과 같아야 함. 기대 45 / Hp 55, 결과 " + a + " / " + burst.Hp;
            Enemy weak = new ArmoredEnemy("knight", 100, 1, 5);
            int c = weak.TakeBurst(4, 8);
            return c == 12 && weak.Hp == 88 ? null : "방어 5 에 TakeBurst(4, 8): 기대 12 / Hp 88, 결과 " + c + " / " + weak.Hp;
        });

        Run("base-contract-kept", () =>
        {
            var makers = new System.Func<Enemy>[] { () => new Enemy("grunt", 30, 2), () => new FlyingEnemy("bat", 30, 2, 7), () => new ShieldedEnemy("mage", 30, 2, 0), () => new ArmoredEnemy("knight", 30, 2, 0) };
            foreach (var make in makers)
            {
                Enemy e = make();
                string name = e.GetType().Name;
                string t = Thrown(() => e.TakeDamage(-1));
                if (t != "ArgumentOutOfRangeException") return name + ".TakeDamage(-1): 기대 ArgumentOutOfRangeException, 결과 " + t;
                if (e.TakeDamage(0) != 0 || e.TakeBurst(0, 10) != 0 || e.Hp != 30) return name + ": 0 피해 / 0 타는 반환 0 이고 Hp 를 바꾸지 않아야 함";
                int r = e.TakeBurst(2, 12);
                if (r != 24 || e.Hp != 6) return name + "(보호막·방어 0).TakeBurst(2, 12): 기대 24 / Hp 6, 결과 " + r + " / " + e.Hp;
                r = e.TakeDamage(50);
                if (r != 6 || e.Hp != 0 || !e.IsDead) return name + ": 남은 Hp 6 에 TakeDamage(50) 은 반환 6 / Hp 0 이어야 함 (반환 " + r + ", Hp " + e.Hp + ")";
                e.Walk(3);
                if (e.X != 6) return name + ".Walk(3) (Speed 2): 기대 X 6, 결과 " + e.X;
            }
            return null;
        });

        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(77);
            string[] kinds = { "Enemy", "FlyingEnemy", "ShieldedEnemy", "ArmoredEnemy" };
            for (int round = 0; round < 400; round++)
            {
                var m = new Model { Kind = rng.Next(4), Hp = rng.Next(1, 120), Speed = rng.Next(0, 5), Shield = rng.Next(0, 40), Armor = rng.Next(0, 12) };
                string desc = kinds[m.Kind] + "(Hp " + m.Hp + ", 보호막 " + m.Shield + ", 방어 " + m.Armor + ")";
                Enemy e = Make(m);
                for (int step = 0; step < 12; step++)
                {
                    int op = rng.Next(3), amount = rng.Next(0, 30), hits = rng.Next(0, 4);
                    int got, exp; string call;
                    if (op == 0) { got = e.TakeDamage(amount); exp = m.Damage(amount); call = "TakeDamage(" + amount + ")"; }
                    else if (op == 1) { got = e.TakeBurst(hits, amount); exp = m.Burst(hits, amount); call = "TakeBurst(" + hits + ", " + amount + ")"; }
                    else { e.Walk(hits); m.X += hits * m.Speed; got = e.X; exp = m.X; call = "Walk(" + hits + ") 뒤 X"; }
                    if (got != exp || e.Hp != m.Hp)
                        return "라운드 " + round + " " + desc + " 의 " + (step + 1) + "번째 호출 " + call + ": 기대 " + exp + " / Hp " + m.Hp + ", 결과 " + got + " / Hp " + e.Hp;
                }
            }
            return null;
        });
    }
}

