problems.solutionCode:
using System;
using System.Collections.Generic;

public enum ModifierKind
{
    Add,        // v = v + value
    Multiply    // value 는 퍼센트. v = v * (100 + value) / 100  (long 나눗셈, 0 쪽으로 버림)
}

public sealed class Stat
{
    private struct Entry
    {
        public int Id;
        public ModifierKind Kind;
        public int Value;
        public int Order;
        public object Source;
    }

    // 항상 적용 순서(order 오름차순, 같으면 추가 순서)로 정렬된 상태를 유지한다.
    private readonly List<Entry> _mods = new List<Entry>();
    private int _baseValue;
    private int _nextId = 1;

    // 더티 플래그: 입력(기본값, 수정자 목록)이 바뀔 때만 다시 계산한다.
    private bool _dirty = true;
    private long _cached;

    public Stat(int baseValue)
    {
        _baseValue = baseValue;
    }

    public int BaseValue
    {
        get { return _baseValue; }
        set
        {
            if (_baseValue == value) return;
            _baseValue = value;
            _dirty = true;
        }
    }

    public int ModifierCount
    {
        get { return _mods.Count; }
    }

    public int AddModifier(ModifierKind kind, int value, int order, object source)
    {
        Entry entry = new Entry { Id = _nextId++, Kind = kind, Value = value, Order = order, Source = source };

        // 뒤에서부터 자리를 찾는다. order 가 더 큰 것만 건너뛰므로 같은 order 끼리는 추가 순서가 유지된다.
        int index = _mods.Count;
        while (index > 0 && _mods[index - 1].Order > order) index--;
        _mods.Insert(index, entry);

        _dirty = true;
        return entry.Id;
    }

    public bool RemoveModifier(int id)
    {
        for (int i = 0; i < _mods.Count; i++)
        {
            if (_mods[i].Id != id) continue;
            _mods.RemoveAt(i);      // 나머지의 상대 순서는 그대로다
            _dirty = true;
            return true;
        }
        return false;
    }

    public int RemoveAllFromSource(object source)
    {
        if (source == null) return 0;
        int removed = 0;
        for (int i = _mods.Count - 1; i >= 0; i--)
        {
            if (!ReferenceEquals(_mods[i].Source, source)) continue;
            _mods.RemoveAt(i);
            removed++;
        }
        if (removed > 0) _dirty = true;
        return removed;
    }

    public long Value
    {
        get
        {
            if (_dirty)
            {
                _cached = Recalculate();
                _dirty = false;
            }
            return _cached;
        }
    }

    // 항상 기본값에서 다시 시작한다. 제거할 때 "역연산"으로 되돌리지 않는 이유는 버림 때문에 역연산이 정확하지 않아서다.
    private long Recalculate()
    {
        long v = _baseValue;
        for (int i = 0; i < _mods.Count; i++)
        {
            Entry m = _mods[i];
            if (m.Kind == ModifierKind.Add) v += m.Value;
            else v = v * (100 + m.Value) / 100;
        }
        return v;
    }
}

