problems.solutionCode:
using System;
using System.Collections.Generic;

// 계층형 상태 기계. 상태는 문자열 id 로 구분하고, 부모 id 로 트리를 만든다.
public sealed class HierarchicalStateMachine
{
    private sealed class Node
    {
        public string Id;
        public Node Parent;
        public Node InitialChild;
        public Action OnEnter;
        public Action OnExit;
        public bool Active;                           // 활성 경로 위에 있는가
        public Dictionary<string, Node> Transitions;  // trigger -> 대상 (전이가 없는 상태는 null)
    }

    private readonly Dictionary<string, Node> _nodes = new Dictionary<string, Node>();
    private readonly Queue<string> _pending = new Queue<string>();   // 아직 처리하지 않은 트리거
    private readonly List<Node> _entryPath = new List<Node>();       // 진입 경로용 재사용 버퍼
    private Node _current;
    private bool _started;
    private bool _processing;    // 전이를 실행하는 중인가 (이때 들어온 Fire 는 큐에만 넣는다)

    public string Current
    {
        get { return _current == null ? null : _current.Id; }
    }

    public bool IsIn(string id)
    {
        Node node;
        return id != null && _nodes.TryGetValue(id, out node) && node.Active;
    }

    public void AddState(string id, string parentId, Action onEnter, Action onExit)
    {
        if (id == null) throw new ArgumentNullException(nameof(id));
        if (_nodes.ContainsKey(id)) throw new ArgumentException("이미 등록된 상태: " + id, nameof(id));
        Node parent = parentId == null ? null : Find(parentId, nameof(parentId));
        _nodes.Add(id, new Node { Id = id, Parent = parent, OnEnter = onEnter, OnExit = onExit });
    }

    public void SetInitialChild(string parentId, string childId)
    {
        Node parent = Find(parentId, nameof(parentId));
        Node child = Find(childId, nameof(childId));
        if (child.Parent != parent) throw new ArgumentException(childId + " 는 " + parentId + " 의 직계 자식이 아님", nameof(childId));
        parent.InitialChild = child;
    }

    public void AddTransition(string fromId, string trigger, string toId)
    {
        if (trigger == null) throw new ArgumentNullException(nameof(trigger));
        Node from = Find(fromId, nameof(fromId));
        Node to = Find(toId, nameof(toId));
        if (from.Transitions == null) from.Transitions = new Dictionary<string, Node>();
        from.Transitions[trigger] = to;
    }

    public void Start(string id)
    {
        if (_started) throw new InvalidOperationException("이미 시작했음");
        Node target = Find(id, nameof(id));
        _started = true;
        _processing = true;
        try
        {
            TransitionTo(target);   // 활성 상태가 없으므로 최상위 조상부터 진입한다
            Drain();                // 진입 훅이 보낸 트리거 처리
        }
        finally { _processing = false; }
    }

    public void Fire(string trigger)
    {
        if (trigger == null) throw new ArgumentNullException(nameof(trigger));
        if (!_started) throw new InvalidOperationException("Start 전에는 Fire 할 수 없음");
        _pending.Enqueue(trigger);
        if (_processing) return;    // 훅 안에서의 호출: 바깥 Drain 이 순서대로 처리한다
        _processing = true;
        try { Drain(); }
        finally { _processing = false; }
    }

    // 큐가 빌 때까지 트리거를 하나씩 끝까지 처리한다 (run-to-completion).
    private void Drain()
    {
        while (_pending.Count > 0)
        {
            string trigger = _pending.Dequeue();
            // 처리하는 시점의 Current 부터 조상 방향으로 찾는다: 자식의 전이가 부모의 것을 가린다.
            for (Node n = _current; n != null; n = n.Parent)
            {
                Node target;
                if (n.Transitions != null && n.Transitions.TryGetValue(trigger, out target))
                {
                    TransitionTo(target);
                    break;
                }
            }
        }
    }

    private void TransitionTo(Node target)
    {
        // 기준 상태: 대상의 진조상 중 활성인 가장 깊은 것 (없으면 null = 트리 바깥).
        // 대상이 비활성이면 Current 와 대상의 최소 공통 조상이고,
        // 대상이 이미 활성이면 대상의 부모라서 대상 자신도 나갔다가 다시 들어간다.
        Node keep = target.Parent;
        while (keep != null && !keep.Active) keep = keep.Parent;

        // 1) 나가기: 안쪽 -> 바깥, 기준 상태 바로 아래까지
        while (_current != keep)
        {
            Node leaving = _current;
            if (leaving.OnExit != null) leaving.OnExit();
            leaving.Active = false;
            _current = leaving.Parent;
        }

        // 2) 들어가기: 기준 상태 바로 아래 -> 대상 (바깥 -> 안쪽)
        _entryPath.Clear();
        for (Node n = target; n != keep; n = n.Parent) _entryPath.Add(n);
        for (int i = _entryPath.Count - 1; i >= 0; i--) Enter(_entryPath[i]);

        // 3) 초기 자식 사슬을 따라 더 내려간다
        for (Node n = target.InitialChild; n != null; n = n.InitialChild) Enter(n);
    }

    private void Enter(Node node)
    {
        node.Active = true;
        _current = node;
        if (node.OnEnter != null) node.OnEnter();
    }

    private Node Find(string id, string paramName)
    {
        Node node;
        if (id == null || !_nodes.TryGetValue(id, out node))
            throw new ArgumentException("등록되지 않은 상태: " + id, paramName);
        return node;
    }
}

