public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    // 로그를 기대값과 비교하고 비운다.
    static string Expect(System.Collections.Generic.List<string> log, string expected, string what)
    {
        string got = string.Join(" ", log);
        log.Clear();
        return got == expected ? null : what + ": 기대 [" + expected + "], 결과 [" + got + "]";
    }

    static string Throws<T>(System.Action act, string what) where T : System.Exception
    {
        try { act(); }
        catch (T) { return null; }
        catch (System.Exception e) { return what + ": " + typeof(T).Name + " 를 기대했지만 " + e.GetType().Name; }
        return what + ": " + typeof(T).Name + " 가 발생하지 않음";
    }

    // 시나리오의 플레이어 트리. 진입은 "+id", 이탈은 "-id" 를 sink 로 보낸다.
    // extraEnter / extraExit: 해당 상태의 훅 안에서 (로그 뒤에) 추가로 실행할 동작.
    static HierarchicalStateMachine Player(System.Action<string> sink,
        System.Collections.Generic.Dictionary<string, System.Action<HierarchicalStateMachine>> extraEnter = null,
        System.Collections.Generic.Dictionary<string, System.Action<HierarchicalStateMachine>> extraExit = null)
    {
        var m = new HierarchicalStateMachine();
        string[,] states = { { "Alive", null }, { "Grounded", "Alive" }, { "Idle", "Grounded" }, { "Run", "Grounded" }, { "Crouch", "Grounded" },
                             { "Airborne", "Alive" }, { "Jump", "Airborne" }, { "Fall", "Airborne" }, { "Dead", null } };
        for (int i = 0; i < states.GetLength(0); i++)
        {
            string id = states[i, 0], plus = "+" + id, minus = "-" + id;
            System.Action<HierarchicalStateMachine> en = null, ex = null;
            if (extraEnter != null) extraEnter.TryGetValue(id, out en);
            if (extraExit != null) extraExit.TryGetValue(id, out ex);
            m.AddState(id, states[i, 1], () => { sink(plus); if (en != null) en(m); }, () => { sink(minus); if (ex != null) ex(m); });
        }
        m.SetInitialChild("Alive", "Grounded");
        m.SetInitialChild("Grounded", "Idle");
        m.SetInitialChild("Airborne", "Jump");
        string[,] tr = { { "Idle", "move", "Run" }, { "Idle", "down", "Crouch" }, { "Idle", "again", "Idle" }, { "Run", "stop", "Idle" },
                         { "Crouch", "up", "Idle" }, { "Crouch", "jump", "Idle" },
                         { "Grounded", "jump", "Airborne" }, { "Grounded", "fell", "Fall" }, { "Grounded", "reset", "Grounded" },
                         { "Jump", "apex", "Fall" }, { "Airborne", "land", "Grounded" },
                         { "Alive", "die", "Dead" }, { "Alive", "respawn", "Alive" }, { "Dead", "revive", "Alive" }, { "Dead", "reviveAir", "Fall" } };
        for (int i = 0; i < tr.GetLength(0); i++) m.AddTransition(tr[i, 0], tr[i, 1], tr[i, 2]);
        return m;
    }

    // 한 번만 실행되는 훅 동작
    static System.Action<HierarchicalStateMachine> Once(System.Action<HierarchicalStateMachine> act)
    {
        bool done = false;
        return m => { if (done) return; done = true; act(m); };
    }

    static System.Collections.Generic.Dictionary<string, System.Action<HierarchicalStateMachine>> Map(string id, System.Action<HierarchicalStateMachine> act)
    {
        return new System.Collections.Generic.Dictionary<string, System.Action<HierarchicalStateMachine>> { { id, act } };
    }

    public static void Main()
    {
        Run("start-and-initial", () =>
        {
            var log = new System.Collections.Generic.List<string>();
            var m = Player(log.Add);
            if (m.Current != null) return "Start 전의 Current 는 null 이어야 함";
            if (m.IsIn("Alive")) return "Start 전에는 IsIn 이 false 여야 함";
            m.Start("Alive");
