            if (e != null) return e;
            if (m.Current != "Idle") return "Start(\"Alive\") 뒤 Current 기대 Idle, 결과 " + m.Current;
            if (!m.IsIn("Alive") || !m.IsIn("Grounded") || !m.IsIn("Idle")) return "Idle 에 있으면 IsIn(Alive / Grounded / Idle) 이 모두 true 여야 함";
            if (m.IsIn("Airborne") || m.IsIn("Run") || m.IsIn("Dead") || m.IsIn("Nope")) return "활성 경로 밖의 상태나 모르는 id 에 IsIn 이 true";
            m.Fire("jump");
