            q.Start("A"); q.Fire("go"); q.Fire("back");
            return q.Current == "A1" && q.IsIn("A") && !q.IsIn("B") ? null : "훅이 모두 null 인 상태들 사이의 전이 뒤 Current 기대 A1, 결과 " + q.Current;
        });

        Run("no-alloc-fire", () =>
        {
            int hooks = 0;
            var m = Player(s => hooks++);
            m.Start("Alive");
            string[] cycle = { "move", "stop", "down", "up", "again", "jump", "apex", "land", "move", "reset", "fell", "land", "nothing", "die", "reviveAir", "respawn" };
            for (int r = 0; r < 300; r++) foreach (string t in cycle) m.Fire(t);
            hooks = 0;
            long before = System.GC.GetAllocatedBytesForCurrentThread();
            for (int r = 0; r < 2000; r++) foreach (string t in cycle) m.Fire(t);
            long bytes = System.GC.GetAllocatedBytesForCurrentThread() - before;
            if (m.Current != "Idle") return "트리거 순환 뒤 Current 기대 Idle, 결과 " + m.Current;
            if (hooks != 2000 * HooksPerCycle) return "훅 호출 횟수 기대 " + (2000 * HooksPerCycle) + ", 결과 " + hooks;
            return bytes == 0 ? null : "Fire " + (2000 * cycle.Length) + "회 동안 " + bytes + "바이트 할당됨 (전이마다 경로용 컬렉션을 새로 만들고 있지 않은가?)";
        });

        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(77031);
            string[] triggers = { "a", "b", "c", "d" };
            for (int round = 0; round < 300; round++)
            {
                int n = rng.Next(3, 13);
                var parent = new int[n]; var initial = new int[n];
                var log = new System.Collections.Generic.List<string>();
                var m = new HierarchicalStateMachine();
                for (int i = 0; i < n; i++)
                {
                    parent[i] = (i == 0 || rng.Next(4) == 0) ? -1 : rng.Next(i);
                    initial[i] = -1;
                    string plus = "+" + i, minus = "-" + i;
                    m.AddState("s" + i, parent[i] < 0 ? null : "s" + parent[i], () => log.Add(plus), () => log.Add(minus));
                }
                for (int i = n - 1; i > 0; i--)
                    if (parent[i] >= 0 && rng.Next(10) < 6) { initial[parent[i]] = i; m.SetInitialChild("s" + parent[i], "s" + i); }
                var table = new System.Collections.Generic.Dictionary<string, int>();
                for (int k = 0; k < 2 * n; k++)
                {
                    int from = rng.Next(n), to = rng.Next(n); string t = triggers[rng.Next(4)];
                    if (table.ContainsKey(from + t)) continue;
                    table[from + t] = to; m.AddTransition("s" + from, t, "s" + to);
                }
                var refLog = new System.Collections.Generic.List<string>();
                var path = new System.Collections.Generic.List<int>();   // 참조 모델의 활성 경로 (바깥 -> 안쪽)
                System.Action<int> go = target =>
                {
                    var tp = new System.Collections.Generic.List<int>();
                    for (int x = target; x >= 0; x = parent[x]) tp.Insert(0, x);
                    int common = 0;
                    while (common < tp.Count && common < path.Count && tp[common] == path[common]) common++;
                    if (common == tp.Count) common--;                    // 대상이 이미 활성: 대상 자신도 다시 들어간다
                    for (int k = path.Count - 1; k >= common; k--) { refLog.Add("-" + path[k]); path.RemoveAt(k); }
                    for (int k = common; k < tp.Count; k++) { refLog.Add("+" + tp[k]); path.Add(tp[k]); }
                    for (int x = initial[target]; x >= 0; x = initial[x]) { refLog.Add("+" + x); path.Add(x); }
                };
                int start = rng.Next(n);
                m.Start("s" + start); go(start);
                for (int step = 0; step <= 30; step++)
                {
                    string got = string.Join(" ", log), exp = string.Join(" ", refLog);
                    if (got != exp) return "라운드 " + round + ", " + step + "번째 Fire 뒤 훅 순서: 기대 [" + exp + "], 결과 [" + got + "]";
                    string cur = "s" + path[path.Count - 1];
                    if (m.Current != cur) return "라운드 " + round + ": Current 기대 " + cur + ", 결과 " + m.Current;
                    for (int i = 0; i < n; i++)
                        if (m.IsIn("s" + i) != path.Contains(i)) return "라운드 " + round + ": IsIn(s" + i + ") 기대 " + path.Contains(i);
                    log.Clear(); refLog.Clear();
                    string t = triggers[rng.Next(4)];
                    m.Fire(t);
                    for (int k = path.Count - 1; k >= 0; k--)
                    {
                        int to;
                        if (table.TryGetValue(path[k] + t, out to)) { go(to); break; }
                    }
                }
            }
            return null;
        });
    }

    const int HooksPerCycle = 48;
}

