    public void Damage(int amount)
    {
        Set(_current - amount);
    }

    public void Heal(int amount)
    {
        Set(_current + amount);
    }

    // 값을 [0, Max] 범위로 잘라 넣고, 바뀌었으면 구독자에게 알린다.
