using System;
using System.Collections.Generic;

// 체력 값 하나를 가진 주체(Subject). 값이 바뀌면 구독자에게 (이전 값, 새 값) 을 알린다.
public sealed class Health
{
    private readonly struct Change
    {
        public readonly int Previous;
        public readonly int Current;
        public Change(int previous, int current) { Previous = previous; Current = current; }
    }

    private readonly List<Action<int, int>> _listeners = new List<Action<int, int>>();
    private readonly Queue<Change> _pending = new Queue<Change>();   // 아직 알리지 않은 변경 (일어난 순서)
    private int _current;
    private bool _notifying;

    public Health(int max)
    {
        if (max <= 0) throw new ArgumentOutOfRangeException(nameof(max));
        Max = max;
        _current = max;
    }

    public int Max { get; }

    public int Current
    {
        get { return _current; }
    }

    // onChanged(previous, current): 값이 바뀔 때마다 구독한 순서대로 호출된다.
    public void Subscribe(Action<int, int> onChanged)
    {
        if (onChanged == null) throw new ArgumentNullException(nameof(onChanged));
        _listeners.Add(onChanged);
    }

    public void Damage(int amount)
    {
        Set(_current - amount);
    }

    public void Heal(int amount)
    {
        Set(_current + amount);
    }

    // 값을 [0, Max] 범위로 잘라 넣고, 바뀌었으면 구독자에게 알린다.
    public void Set(int value)
    {
        // 1) 먼저 자르고, 자른 값으로 "바뀌었는가"를 판단한다.
        int next = Math.Clamp(value, 0, Max);
        if (next == _current) return;

        // 2) 상태를 먼저 확정한다. 이 뒤로는 누가 Current 를 읽어도 새 값이다.
        int previous = _current;
        _current = next;

        // 3) 통지는 일어난 순서대로 줄을 세운다.
        _pending.Enqueue(new Change(previous, next));
        if (_notifying) return;   // 핸들러 안에서 일어난 변경: 바깥 루프가 차례가 오면 알린다

        _notifying = true;
        try
        {
            while (_pending.Count > 0)
            {
                Change change = _pending.Dequeue();
                for (int i = 0; i < _listeners.Count; i++)
                    _listeners[i](change.Previous, change.Current);
            }
        }
        finally
        {
            // 핸들러가 예외를 던져도 다음 호출이 막히지 않게 한다. 전달하지 못한 통지는 버린다.
            _notifying = false;
            _pending.Clear();
        }
    }
}

