problems.solutionCode:
using System;
using System.Collections.Generic;

// 시스템 사이의 메시지를 중개하는 버스. 전역 static 이 아니라 필요한 곳에 인스턴스를 넘겨서 쓴다.
public sealed class EventBus
{
    // 타입을 지운 채널: 버스의 배달 순서 큐가 "다음은 어느 타입 차례인가"만 기억하면 된다.
    private interface IChannel
    {
        void DeliverNext();
    }

    // 메시지 타입 하나의 구독 목록과, 아직 배달하지 않은 그 타입의 메시지들.
    private sealed class Channel<T> : IChannel
    {
        public readonly List<Subscription<T>> Subs = new List<Subscription<T>>();
        public readonly Queue<T> Pending = new Queue<T>();
        public int LiveCount;
        private bool _delivering;
        private bool _hasDead;

        public void DeliverNext()
        {
            T message = Pending.Dequeue();
            int count = Subs.Count;
            _delivering = true;
            try
            {
                for (int i = 0; i < count; i++)
                {
                    Subscription<T> sub = Subs[i];
                    if (sub.Active) sub.Handler(message);   // 배달 도중 해지된 구독은 건너뛴다
                }
            }
            finally
            {
                _delivering = false;
                if (_hasDead) { Subs.RemoveAll(IsDead); _hasDead = false; }
            }
        }

        public void Remove(Subscription<T> sub)
        {
            LiveCount--;
            if (_delivering) _hasDead = true;    // 순회 중인 목록은 건드리지 않고 표시만 한다
            else Subs.Remove(sub);
        }

        private static readonly Predicate<Subscription<T>> IsDead = s => !s.Active;
    }

    // 구독 하나 = 해지 토큰 하나.
    private sealed class Subscription<T> : IDisposable
    {
        public Action<T> Handler;
        public bool Active = true;
        private Channel<T> _channel;

        public Subscription(Channel<T> channel, Action<T> handler)
        {
            _channel = channel;
            Handler = handler;
        }

        public void Dispose()
        {
            if (!Active) return;     // 두 번째 호출부터는 아무 일도 하지 않는다
            Active = false;
            Handler = null;          // 토큰을 오래 들고 있어도 구독자를 붙잡지 않는다
            _channel.Remove(this);
            _channel = null;
        }
    }

    private readonly Dictionary<Type, IChannel> _channels = new Dictionary<Type, IChannel>();
    private readonly Queue<IChannel> _order = new Queue<IChannel>();   // 발행된 순서 (타입을 가로질러)
    private bool _delivering;

    public IDisposable Subscribe<T>(Action<T> handler)
    {
        if (handler == null) throw new ArgumentNullException(nameof(handler));
        Channel<T> channel = GetChannel<T>();
        var sub = new Subscription<T>(channel, handler);
        channel.Subs.Add(sub);
        channel.LiveCount++;
        return sub;
    }

    public void Publish<T>(T message)
    {
        // 구독자가 없는 타입도 같은 길로 간다: 차례가 오면 빈 목록을 돌고 끝난다.
        Channel<T> channel = GetChannel<T>();
        channel.Pending.Enqueue(message);
        _order.Enqueue(channel);
        if (_delivering) return;     // 핸들러 안에서의 발행: 바깥 루프가 순서대로 배달한다

        _delivering = true;
        try
        {
            while (_order.Count > 0) _order.Dequeue().DeliverNext();
        }
        finally
        {
            _delivering = false;
        }
    }

    public int CountSubscribers<T>()
    {
        IChannel channel;
        return _channels.TryGetValue(typeof(T), out channel) ? ((Channel<T>)channel).LiveCount : 0;
    }

    public SubscriptionScope CreateScope()
    {
        return new SubscriptionScope(this);
    }

    private Channel<T> GetChannel<T>()
    {
        IChannel channel;
        if (!_channels.TryGetValue(typeof(T), out channel))
        {
            channel = new Channel<T>();
            _channels.Add(typeof(T), channel);
        }
        return (Channel<T>)channel;
    }
}

// 화면 하나, 전투 한 판처럼 수명이 같은 구독들의 묶음. Dispose 하면 이 범위로 만든 구독이 모두 해지된다.
public sealed class SubscriptionScope : IDisposable
{
    private readonly EventBus _bus;
    private readonly List<IDisposable> _tokens = new List<IDisposable>();
    private bool _disposed;

    internal SubscriptionScope(EventBus bus)
    {
        _bus = bus;
    }

    public void Subscribe<T>(Action<T> handler)
    {
        if (_disposed) throw new ObjectDisposedException(nameof(SubscriptionScope));
        _tokens.Add(_bus.Subscribe(handler));
    }

    public void Dispose()
    {
        if (_disposed) return;
        _disposed = true;
        for (int i = 0; i < _tokens.Count; i++) _tokens[i].Dispose();
        _tokens.Clear();
    }
}

