            if (bus.CountSubscribers<int>() != 0) return "빈 버스의 CountSubscribers<int>() 가 0 이 아님";
            bus.Publish(0); bus.Publish("nobody");
            var scope = bus.CreateScope();
            var ta = bus.Subscribe<int>(v => log.Add("A" + v));
            scope.Subscribe<int>(v => log.Add("B" + v));
            bus.Subscribe<string>(s => log.Add("C" + s));
            scope.Subscribe<int>(v => log.Add("D" + v));
            bus.Publish(1); bus.Publish("x"); bus.Publish(2.5);
            string e = Expect(log, "A1 B1 D1 Cx", "Publish(1), Publish(\"x\"), Publish(2.5): 타입별로, 구독한 순서대로 (범위 구독과 직접 구독이 한 줄)");
            if (e != null) return e;
            if (bus.CountSubscribers<int>() != 3 || bus.CountSubscribers<string>() != 1 || bus.CountSubscribers<double>() != 0)
                return "CountSubscribers 기대 int 3 / string 1 / double 0, 결과 " + bus.CountSubscribers<int>() + " / " + bus.CountSubscribers<string>() + " / " + bus.CountSubscribers<double>();
            ta.Dispose(); ta.Dispose(); ta.Dispose();
            if (bus.CountSubscribers<int>() != 2) return "토큰 하나를 세 번 Dispose 한 뒤 CountSubscribers<int>() 기대 2, 결과 " + bus.CountSubscribers<int>();
            bus.Publish(2);
            e = Expect(log, "B2 D2", "A 해지 후 Publish(2)");
            if (e != null) return e;
            System.Action<int> h = v => log.Add("H" + v);
            var t1 = bus.Subscribe(h); bus.Subscribe(h);
            t1.Dispose();
            bus.Publish(3);
            e = Expect(log, "B3 D3 H3", "같은 델리게이트를 두 번 구독하고 첫 토큰만 해지");
            if (e != null) return e;
            try { bus.Subscribe<int>(null); return "Subscribe(null) 이 예외를 던지지 않음"; }
            catch (System.ArgumentNullException) { }
            return null;
        });

        Run("exact-type-and-instances", () =>
        {
            var bus = new EventBus();
            var log = new System.Collections.Generic.List<string>();
            bus.Subscribe<object>(o => log.Add("obj:" + o));
            bus.Subscribe<string>(s => log.Add("str:" + s));
            bus.Subscribe<__Hit>(x => log.Add("hit:" + x.Target + "/" + x.Amount));
            bus.Subscribe<__BaseMsg>(b => log.Add("base"));
            bus.Publish("a");
            string e = Expect(log, "str:a", "Publish(\"a\") 는 T = string 구독자에게만");
            if (e != null) return e;
            bus.Publish<object>("b");
            e = Expect(log, "obj:b", "Publish<object>(\"b\") 는 T = object 구독자에게만 (실제 값의 타입이 아니라 타입 인자 기준)");
            if (e != null) return e;
            bus.Publish(new __Hit(3, 7));
            e = Expect(log, "hit:3/7", "구조체 메시지");
            if (e != null) return e;
            bus.Publish(new __DerivedMsg());
            e = Expect(log, "", "Publish<Derived> 는 Subscribe<Base> 구독자에게 가지 않아야 함");
            if (e != null) return e;
            bus.Publish<__BaseMsg>(new __DerivedMsg());
            e = Expect(log, "base", "Publish<Base>(new Derived())");
            if (e != null) return e;
            var other = new EventBus();
            other.Subscribe<string>(s => log.Add("other:" + s));
            if (bus.CountSubscribers<string>() != 1 || other.CountSubscribers<object>() != 0) return "버스 인스턴스 둘의 구독이 섞임 (static 저장소를 쓰고 있지 않은가?)";
            other.Publish("c");
            e = Expect(log, "other:c", "두 번째 버스에 Publish: 첫 번째 버스의 구독자는 받지 않아야 함");
            if (e != null) return e;
            bus.Publish("d");
            return Expect(log, "str:d", "첫 번째 버스에 Publish: 두 번째 버스의 구독자는 받지 않아야 함");
        });

        Run("publish-inside-handler-queued", () =>
        {
            var bus = new EventBus();
            var log = new System.Collections.Generic.List<string>();
            bus.Subscribe<int>(v => { log.Add("A" + v); if (v == 1) { bus.Publish("s"); bus.Publish(2); log.Add("A1end"); } });
            bus.Subscribe<int>(v => log.Add("B" + v));
            bus.Subscribe<string>(s => { log.Add("S" + s); if (s == "s") bus.Publish(3); });
            bus.Publish(1);
            string e = Expect(log, "A1 A1end B1 Ss A2 B2 A3 B3", "A 가 1 을 받고 \"s\", 2 를 발행하고, S 가 \"s\" 를 받고 3 을 발행 (Publish(1) 이 반환한 직후의 로그)");
            if (e != null) return e;
            bus.Publish(9);
            e = Expect(log, "A9 B9", "핸들러 밖의 Publish 는 반환 전에 배달이 끝나야 함");
            if (e != null) return e;
            var bus2 = new EventBus();
            bus2.Subscribe<int>(v => { log.Add("X" + v); if (v == 1) { bus2.Publish(2.5); bus2.Publish(2); } });
            bus2.Publish(1);
            return Expect(log, "X1 X2", "핸들러가 구독자 없는 타입(double)과 2 를 차례로 발행: 빈 타입은 조용히 지나가고 2 는 배달되어야 함");
        });

        Run("unsubscribe-during-delivery", () =>
        {
            var bus = new EventBus();
            var log = new System.Collections.Generic.List<string>();
            System.IDisposable tb = null, td = null, ts = null;
            bus.Subscribe<int>(v => { log.Add("A" + v); if (v == 1) td.Dispose(); });
            tb = bus.Subscribe<int>(v => { log.Add("B" + v); tb.Dispose(); });
            bus.Subscribe<int>(v => log.Add("C" + v));
            td = bus.Subscribe<int>(v => log.Add("D" + v));
            bus.Publish(1);
            string e = Expect(log, "A1 B1 C1", "A 가 아직 차례가 오지 않은 D 를 해지하고 B 가 자기 자신을 해지");
            if (e != null) return e;
            if (bus.CountSubscribers<int>() != 2) return "CountSubscribers<int>() 기대 2, 결과 " + bus.CountSubscribers<int>();
            bus.Publish(2);
            e = Expect(log, "A2 C2", "그다음 Publish");
            if (e != null) return e;
            ts = bus.Subscribe<string>(s => log.Add("S" + s));
            bus.Subscribe<int>(v => { if (v == 5) { bus.Publish("queued"); ts.Dispose(); } });
            bus.Publish(5);
            return Expect(log, "A5 C5", "핸들러가 \"queued\" 를 발행한 직후 string 구독을 해지: 큐에 있던 메시지도 받으면 안 됨");
        });

        Run("scope-dispose", () =>
        {
            var bus = new EventBus();
            var log = new System.Collections.Generic.List<string>();
            var scope = bus.CreateScope();
            scope.Subscribe<int>(v => log.Add("P" + v));
            bus.Subscribe<int>(v => log.Add("R" + v));
            scope.Subscribe<string>(s => log.Add("Q" + s));
            scope.Subscribe<int>(v => log.Add("T" + v));
            scope.Dispose();
            if (bus.CountSubscribers<int>() != 1 || bus.CountSubscribers<string>() != 0) return "scope.Dispose() 뒤 CountSubscribers 기대 int 1 / string 0, 결과 " + bus.CountSubscribers<int>() + " / " + bus.CountSubscribers<string>();
            scope.Dispose();
            if (bus.CountSubscribers<int>() != 1) return "scope.Dispose() 를 두 번 부르면 구독 수가 또 줄어듦";
            bus.Publish(1); bus.Publish("x");
            string e = Expect(log, "R1", "범위를 닫은 뒤에는 범위 밖의 구독 R 만 받아야 함");
            if (e != null) return e;
            try { scope.Subscribe<int>(v => log.Add("Z" + v)); return "닫힌 범위의 Subscribe 가 ObjectDisposedException 을 던지지 않음"; }
            catch (System.ObjectDisposedException) { }
            if (bus.CountSubscribers<int>() != 1) return "닫힌 범위의 Subscribe 가 구독을 추가함";

            var screen = bus.CreateScope(); var battle = bus.CreateScope();
            screen.Subscribe<int>(v => { log.Add("U" + v); if (v == 5) screen.Dispose(); });
            battle.Subscribe<int>(v => log.Add("B" + v));
            screen.Subscribe<int>(v => log.Add("V" + v));
            screen.Subscribe<string>(s => log.Add("W" + s));
            bus.Publish(4);
            e = Expect(log, "R4 U4 B4 V4", "범위 둘과 직접 구독이 섞인 Publish(4)");
            if (e != null) return e;
            bus.Publish(5); bus.Publish("y"); bus.Publish(6);
            e = Expect(log, "R5 U5 B5 R6 B6", "U 가 핸들러 안에서 자기 범위(screen)를 닫음: 같은 범위의 V 는 이번 메시지부터 받지 않고, 다른 범위의 B 는 영향 없음");
            if (e != null) return e;
            return bus.CountSubscribers<int>() == 2 ? null : "CountSubscribers<int>() 기대 2, 결과 " + bus.CountSubscribers<int>();
        });

        Run("random-vs-reference", () =>
        {
            // 구독 k 는 처음 호출될 때 한 번 act[k] 를 한다:
            // 0 없음, 1 int 발행, 2 string 발행, 3 구독 arg[k] 의 토큰 해지, 5 범위 arg[k] 닫기
            var rng = new System.Random(90417);
            for (int round = 0; round < 300; round++)
            {
                var bus = new EventBus();
                var scopes = new[] { bus.CreateScope(), bus.CreateScope() };
                var log = new System.Collections.Generic.List<string>();
                var refLog = new System.Collections.Generic.List<string>();
                var type = new System.Collections.Generic.List<int>();      // 0 = int, 1 = string
                var owner = new System.Collections.Generic.List<int>();     // -1 직접, 0/1 범위
                var act = new System.Collections.Generic.List<int>();
                var arg = new System.Collections.Generic.List<int>();
                var fired = new System.Collections.Generic.List<bool>();
                var tokens = new System.Collections.Generic.List<System.IDisposable>();
                int counter = 100;
                System.Action<int, int, int, int> add = null;
                System.Action<int, string> onCall = (k, text) =>
                {
                    log.Add(k + ":" + text);
                    if (fired[k]) return;
                    fired[k] = true;
                    if (act[k] == 1) bus.Publish(counter++);
                    else if (act[k] == 2) bus.Publish("s" + counter++);
                    else if (act[k] == 3) tokens[arg[k]].Dispose();
                    else if (act[k] == 5) scopes[arg[k]].Dispose();
                };
                add = (t, own, a, g) =>
                {
                    int k = type.Count;
                    type.Add(t); owner.Add(own); act.Add(a); arg.Add(g); fired.Add(false); tokens.Add(null);
                    if (t == 0) { System.Action<int> h = v => onCall(k, "" + v); if (own < 0) tokens[k] = bus.Subscribe(h); else scopes[own].Subscribe(h); }
                    else { System.Action<string> h = s => onCall(k, s); if (own < 0) tokens[k] = bus.Subscribe(h); else scopes[own].Subscribe(h); }
                };
                int n0 = rng.Next(2, 8);
                var owners0 = new int[n0];
                for (int i = 0; i < n0; i++) owners0[i] = rng.Next(4) == 0 ? rng.Next(2) : -1;
                for (int i = 0; i < n0; i++)
                {
                    int a = rng.Next(8); a = a >= 6 ? 0 : a;
                    int g = 0;
                    if (a == 3) { g = rng.Next(n0); if (owners0[g] >= 0) a = 0; }
                    else if (a == 4 || a == 5) { g = rng.Next(2); if (a == 4) a = 0; }   // 4 는 쓰지 않는다 (핸들러 안의 구독은 범위 밖)
                    add(rng.Next(2), owners0[i], a, g);
                }
                // 참조 모델
                var rType = new System.Collections.Generic.List<int>(type); var rOwner = new System.Collections.Generic.List<int>(owner);
                var rAct = new System.Collections.Generic.List<int>(act); var rArg = new System.Collections.Generic.List<int>(arg);
                var rFired = new System.Collections.Generic.List<bool>(); var rAlive = new System.Collections.Generic.List<bool>();
                for (int i = 0; i < n0; i++) { rFired.Add(false); rAlive.Add(true); }
                int rCounter = 100;
                var queue = new System.Collections.Generic.Queue<string[]>();
                for (int p = 0; p < 3; p++)
                {
                    int pt = rng.Next(2);
                    if (pt == 0) bus.Publish(p); else bus.Publish("p" + p);
                    queue.Enqueue(new[] { "" + pt, pt == 0 ? "" + p : "p" + p });
                    while (queue.Count > 0)
                    {
                        string[] msg = queue.Dequeue();
                        int snapshot = rType.Count;
                        for (int k = 0; k < snapshot; k++)
                        {
                            if (!rAlive[k] || "" + rType[k] != msg[0]) continue;
                            refLog.Add(k + ":" + msg[1]);
                            if (rFired[k]) continue;
                            rFired[k] = true;
                            if (rAct[k] == 1) queue.Enqueue(new[] { "0", "" + rCounter++ });
                            else if (rAct[k] == 2) queue.Enqueue(new[] { "1", "s" + rCounter++ });
                            else if (rAct[k] == 3) rAlive[rArg[k]] = false;
                            else if (rAct[k] == 5) { for (int j = 0; j < rOwner.Count; j++) if (rOwner[j] == rArg[k]) rAlive[j] = false; }
                        }
                    }
                    string got = string.Join(" ", log), exp = string.Join(" ", refLog);
                    if (got != exp) return "라운드 " + round + ", " + (p + 1) + "번째 Publish 뒤 (구독번호:값): 기대 [" + exp + "], 결과 [" + got + "]";
                    int li = 0, ls = 0;
                    for (int k = 0; k < rAlive.Count; k++) if (rAlive[k]) { if (rType[k] == 0) li++; else ls++; }
                    if (bus.CountSubscribers<int>() != li || bus.CountSubscribers<string>() != ls)
                        return "라운드 " + round + ": CountSubscribers 기대 int " + li + " / string " + ls + ", 결과 " + bus.CountSubscribers<int>() + " / " + bus.CountSubscribers<string>();
                    log.Clear(); refLog.Clear();
                }
            }
            return null;
        });
    }
}

