using System;

// 실제 시스템 시계.
public sealed class SystemClock
{
    public DateTime UtcNow
    {
        get { return DateTime.UtcNow; }
    }
}

// 출석 보상 규칙: UTC 날짜가 바뀌면 다시 받을 수 있다.
public sealed class DailyReward
{
    private readonly SystemClock _clock = new SystemClock();   // 쓸 시계를 안에서 직접 만든다
    private DateTime? _lastClaimDate;

    public bool CanClaim()
    {
        return _lastClaimDate == null || _clock.UtcNow.Date > _lastClaimDate.Value;
    }

    public bool TryClaim()
    {
        if (!CanClaim()) return false;
        _lastClaimDate = _clock.UtcNow.Date;
        return true;
    }
}

// 로비 화면: 출석 보상 버튼의 문구를 정하고, 버튼 입력을 규칙에 전달한다.
public sealed class LobbyScreen
{
    private readonly DailyReward _reward = new DailyReward();  // 쓸 규칙 객체도 안에서 직접 만든다

    public string BuildButtonText()
    {
        return _reward.CanClaim() ? "보상 받기" : "내일 다시 오세요";
    }

    public bool OnClaimButton()
    {
        return _reward.TryClaim();
    }
}

