using System;

// 출석 보상 규칙이 시계에게 바라는 것 전부. 규칙 쪽이 정한 인터페이스다.
public interface IClock
{
    DateTime UtcNow { get; }
}

// 실제 시스템 시계.
public sealed class SystemClock : IClock
{
    public DateTime UtcNow
    {
        get { return DateTime.UtcNow; }
    }
}

// 테스트용 시계: 시간을 원하는 값으로 정할 수 있다.
public sealed class FakeClock : IClock
{
    public DateTime UtcNow { get; set; }

    public FakeClock(DateTime start)
    {
        UtcNow = start;
    }
}

// 출석 보상 규칙: UTC 날짜가 바뀌면 다시 받을 수 있다.
public sealed class DailyReward
{
    private readonly IClock _clock;        // 어떤 시계인지는 모른다. 만들지도 않는다.
    private DateTime? _lastClaimDate;

    // 생성자 주입: 시계 없이는 이 객체를 만들 수 없다.
    public DailyReward(IClock clock)
    {
        if (clock == null) throw new ArgumentNullException(nameof(clock));
        _clock = clock;
    }

    public bool CanClaim()
    {
        return _lastClaimDate == null || _clock.UtcNow.Date > _lastClaimDate.Value;
    }

    public bool TryClaim()
    {
        if (!CanClaim()) return false;
        _lastClaimDate = _clock.UtcNow.Date;
        return true;
    }
}

// 로비 화면: 출석 보상 버튼의 문구를 정하고, 버튼 입력을 규칙에 전달한다.
public sealed class LobbyScreen
{
    private readonly DailyReward _reward;

    // 화면도 규칙 객체를 만들지 않고 받는다. 그래서 시계가 무엇인지 알 필요가 없다.
    public LobbyScreen(DailyReward reward)
    {
        if (reward == null) throw new ArgumentNullException(nameof(reward));
        _reward = reward;
    }

    public string BuildButtonText()
    {
        return _reward.CanClaim() ? "보상 받기" : "내일 다시 오세요";
    }

    public bool OnClaimButton()
    {
        return _reward.TryClaim();
    }
}

// 컴포지션 루트: 구체 클래스를 new 하고 서로 이어 주는 코드는 여기 한 곳에만 있다.
public static class GameBootstrap
{
    public static LobbyScreen CreateLobby()
    {
        IClock clock = new SystemClock();
        DailyReward reward = new DailyReward(clock);
        return new LobbyScreen(reward);
    }
}

// 주입 덕분에 가능해진 검증: 실제로 하루를 기다리지 않고 "자정이 지나면 다시 받을 수 있다"를 확인한다.
public static class DailyRewardCheck
{
    public static bool ClaimAgainAfterMidnight()
    {
        var clock = new FakeClock(new DateTime(2026, 3, 1, 23, 50, 0, DateTimeKind.Utc));
        var reward = new DailyReward(clock);

        bool first = reward.TryClaim();                 // 3월 1일 23:50: 받는다
        bool sameDay = reward.TryClaim();               // 같은 날: 못 받는다
        clock.UtcNow = clock.UtcNow.AddMinutes(20);     // 3월 2일 00:10
        bool nextDay = reward.TryClaim();               // 날짜가 바뀌었다: 받는다

        return first && !sameDay && nextDay;
    }
}

