using System;
using System.Collections.Generic;

// 웨이브에서 한 종류의 적을 몇 마리 내보낼지. (완성된 타입: 고치지 않아도 된다)
public readonly struct SpawnEntry
{
    public string EnemyId { get; }
    public int Count { get; }

    public SpawnEntry(string enemyId, int count)
    {
        EnemyId = enemyId;
        Count = count;
    }
}

// 완성된 웨이브 설정. 만들어진 뒤에는 바뀌지 않는다: setter 가 없고, 목록은 읽기 전용 래퍼로만 내보낸다.
public sealed class WaveConfig
{
    public string Name { get; }
    public float SpawnInterval { get; }
    public IReadOnlyList<SpawnEntry> Spawns { get; }
    public int TotalEnemies { get; }

    // 빌더만 만들 수 있게 internal 로 둔다. spawns 는 빌더가 넘겨준, 다른 누구도 참조하지 않는 복사본이다.
    internal WaveConfig(string name, float spawnInterval, List<SpawnEntry> spawns, int totalEnemies)
    {
        Name = name;
        SpawnInterval = spawnInterval;
        Spawns = spawns.AsReadOnly();
        TotalEnemies = totalEnemies;
    }
}

// WaveConfig 를 단계별로 조립한다. 각 설정 메서드는 this 를 돌려준다.
public sealed class WaveBuilder
{
    public const float DefaultSpawnInterval = 1f;   // WithSpawnInterval 을 부르지 않았을 때의 간격(초)
    public const float MaxSpawnDuration = 60f;      // SpawnInterval * (TotalEnemies - 1) 의 상한(초)

    private readonly List<SpawnEntry> _spawns = new List<SpawnEntry>();
    private string _name;
    private float _spawnInterval = DefaultSpawnInterval;

    // 인자 하나만 보면 알 수 있는 오류는 그 자리에서 던진다. 검사를 통과한 뒤에만 상태를 바꾼다.
    public WaveBuilder Named(string name)
    {
        if (string.IsNullOrEmpty(name)) throw new ArgumentException("웨이브 이름이 비어 있음", nameof(name));
        _name = name;
        return this;
    }

    public WaveBuilder WithSpawnInterval(float seconds)
    {
        if (!(seconds > 0f)) throw new ArgumentOutOfRangeException(nameof(seconds), "스폰 간격은 0 보다 커야 함");
        _spawnInterval = seconds;
        return this;
    }

    public WaveBuilder AddEnemy(string enemyId, int count)
    {
        if (string.IsNullOrEmpty(enemyId)) throw new ArgumentException("적 id 가 비어 있음", nameof(enemyId));
        if (count < 1) throw new ArgumentOutOfRangeException(nameof(count), "마릿수는 1 이상이어야 함");
        _spawns.Add(new SpawnEntry(enemyId, count));
        return this;
    }

    // 여러 설정을 함께 봐야 알 수 있는 오류는 조립이 끝나는 이 시점에만 판단할 수 있다.
    public WaveConfig Build()
    {
        if (_name == null) throw new InvalidOperationException("웨이브 이름이 설정되지 않음 (Named)");
        if (_spawns.Count == 0) throw new InvalidOperationException("적이 하나도 없음 (AddEnemy)");

        int total = 0;
        for (int i = 0; i < _spawns.Count; i++) total += _spawns[i].Count;

        float duration = _spawnInterval * (total - 1);
        if (duration > MaxSpawnDuration)
            throw new InvalidOperationException("스폰에 " + duration + "초가 걸림 (상한 " + MaxSpawnDuration + "초)");

        // 빌더의 목록을 그대로 넘기지 않고 복사본을 넘긴다: 빌더를 계속 써도 이미 만든 설정은 변하지 않는다.
        return new WaveConfig(_name, _spawnInterval, new List<SpawnEntry>(_spawns), total);
    }
}

