using System;
using System.Collections.Generic;

// Q1: 알 수 없다. WaveSpawner 는 매개변수 없는 생성자만 있으므로 new WaveSpawner() 는 언제나 컴파일된다.
//     필요한 서비스는 StartWave 본문 안의 Get<T>() 호출에만 나타나서, 등록을 빠뜨리면 컴파일 오류가 아니라
//     실행 중 그 줄에 도달했을 때 InvalidOperationException 으로 드러난다. IAudio 만 등록되어 있으면
//     효과음이 이미 재생된 뒤에 IAnalytics 에서 실패하므로, 실패가 메서드의 중간에서 일어난다.
// Q2: 생성자가 WaveSpawner(IAudio audio, IAnalytics analytics) 가 되면 필요한 것이 시그니처에 드러나고,
//     둘 중 하나라도 없으면 객체를 만들 수 없다(컴파일 시점, 또는 생성자의 null 검사). 테스트는 전역 상태를
//     건드리지 않고 가짜를 직접 넘기면 되므로 오버라이드를 되돌릴 필요도 없다.

// 게임 코드가 쓰는 서비스 인터페이스 (바꾸지 않는다)
public interface IAudio { void Play(string cue); }
public interface IAnalytics { void Track(string eventName); }

public sealed class ServiceLocator
{
    // 타입 하나의 상태: 기본 제공자 + 살아 있는 오버라이드(시작 순서대로).
    private sealed class Slot
    {
        public object Base;
        public readonly List<Scope> Overrides = new List<Scope>();
    }

    // 오버라이드 하나 = 범위 하나. 제공자가 같은 인스턴스여도 범위는 서로 다른 객체다.
    private sealed class Scope : IDisposable
    {
        private Slot _slot;
        public readonly object Provider;

        public Scope(Slot slot, object provider)
        {
            _slot = slot;
            Provider = provider;
        }

        public void Dispose()
        {
            if (_slot == null) return;            // 두 번째 이후의 Dispose 는 무시한다
            _slot.Overrides.Remove(this);         // 이 범위만 뺀다(참조 비교). 순서가 어긋나도 다른 범위는 그대로
            _slot = null;
        }
    }

    // 키는 Register/Get 에 쓴 제네릭 인자 T 그 자체다(제공자의 실제 타입이 아니다).
    private readonly Dictionary<Type, Slot> _slots = new Dictionary<Type, Slot>();

    public void Register<T>(T provider) where T : class
    {
        if (provider == null) throw new ArgumentNullException(nameof(provider));
        SlotFor(typeof(T)).Base = provider;       // 오버라이드는 건드리지 않는다
    }

    public T Get<T>() where T : class
    {
        T provider;
        if (TryGet(out provider)) return provider;
        throw new InvalidOperationException("서비스가 등록되지 않았습니다: " + typeof(T).Name);
    }

    public bool TryGet<T>(out T provider) where T : class
    {
        Slot slot;
        if (_slots.TryGetValue(typeof(T), out slot))
        {
            int n = slot.Overrides.Count;
            object current = n > 0 ? slot.Overrides[n - 1].Provider : slot.Base;
            if (current != null)
            {
                provider = (T)current;
                return true;
            }
        }
        provider = null;
        return false;
    }

    public IDisposable Override<T>(T provider) where T : class
    {
        if (provider == null) throw new ArgumentNullException(nameof(provider));
        Slot slot = SlotFor(typeof(T));
        var scope = new Scope(slot, provider);
        slot.Overrides.Add(scope);
        return scope;
    }

    private Slot SlotFor(Type type)
    {
        Slot slot;
        if (!_slots.TryGetValue(type, out slot))
        {
            slot = new Slot();
            _slots.Add(type, slot);
        }
        return slot;
    }
}

// 게임 전체가 쓰는 전역 접근점 (바꾸지 않는다)
public static class Game
{
    public static readonly ServiceLocator Services = new ServiceLocator();
}

// 로케이터를 쓰는 기존 게임 코드 (바꾸지 않는다)
public sealed class WaveSpawner
{
    public void StartWave(int wave)
    {
        Game.Services.Get<IAudio>().Play("wave_start");
        Game.Services.Get<IAnalytics>().Track("wave_" + wave);
    }
}

