public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name + " " + e.Message; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    // 지금 Get<IAudio>() 가 돌려주는 제공자의 이름. 없으면 "(없음)".
    static string Cur(ServiceLocator s)
    {
        IAudio a;
        if (!s.TryGet<IAudio>(out a)) return a == null ? "(없음)" : "(TryGet 이 false 인데 out 이 null 이 아님)";
        __Audio fa = a as __Audio;
        return fa == null ? "(알 수 없는 제공자)" : fa.Name;
    }

    static string Expect(ServiceLocator s, string step, string expected)
    {
        string got = Cur(s);
        return got == expected ? null : step + " 뒤 기대 " + expected + " / 결과 " + got;
    }

    static string Throws<TEx>(System.Action act, string what) where TEx : System.Exception
    {
        try { act(); }
        catch (TEx) { return null; }
        catch (System.Exception e) { return what + ": " + typeof(TEx).Name + " 대신 " + e.GetType().Name; }
        return what + ": 예외가 나지 않음";
    }

    public static void Main()
    {
        Run("register-get-missing", () =>
        {
            var s = new ServiceLocator();
            IAudio none;
            if (s.TryGet<IAudio>(out none) || none != null) return "빈 로케이터의 TryGet 이 true 이거나 out 이 null 이 아님";
            try { s.Get<IAudio>(); return "등록 전 Get<IAudio>() 가 예외 없이 반환함"; }
            catch (System.InvalidOperationException e)
            {
                if (e.Message == null || !e.Message.Contains("IAudio")) return "InvalidOperationException 메시지에 IAudio 가 없음: " + e.Message;
            }
            var b1 = new __Audio("B1");
            s.Register<IAudio>(b1);
            if (!object.ReferenceEquals(s.Get<IAudio>(), b1)) return "Register 한 인스턴스를 Get 이 그대로 돌려주지 않음";
            s.Register<IAudio>(new __Audio("B2"));
            string e2 = Expect(s, "같은 타입 재등록", "B2");
            if (e2 != null) return e2;
            return Throws<System.ArgumentNullException>(() => s.Register<IAudio>(null), "Register(null)")
                ?? Throws<System.ArgumentNullException>(() => s.Override<IAudio>(null), "Override(null)")
                ?? Expect(s, "null 인자 거절", "B2");
        });

        Run("key-by-type-argument", () =>
        {
            var s = new ServiceLocator();
            var a = new __Audio("A");
            s.Register<IAudio>(a);
            __Audio concrete;
            if (s.TryGet<__Audio>(out concrete)) return "Register<IAudio> 로 등록했는데 TryGet<__Audio> 가 true (키는 제네릭 인자 T 여야 함)";
            IAnalytics n;
            if (s.TryGet<IAnalytics>(out n)) return "등록하지 않은 IAnalytics 를 TryGet 이 찾음";
            var an = new __Analytics("N");
            s.Register<IAnalytics>(an);
            if (!object.ReferenceEquals(s.Get<IAnalytics>(), an) || !object.ReferenceEquals(s.Get<IAudio>(), a)) return "타입별 등록이 서로 덮어씀";
            return null;
        });

        Run("override-nested-lifo", () =>
        {
            var s = new ServiceLocator();
            s.Register<IAudio>(new __Audio("B"));
            var o1 = s.Override<IAudio>(new __Audio("A1"));
            string e = Expect(s, "Override(A1)", "A1");
            if (e != null) return e;
            var o2 = s.Override<IAudio>(new __Audio("A2"));
            e = Expect(s, "Override(A2)", "A2"); if (e != null) return e;
            o2.Dispose(); e = Expect(s, "A2 해제", "A1"); if (e != null) return e;
            o1.Dispose(); return Expect(s, "A1 해제", "B");
        });

        Run("override-out-of-order", () =>
        {
            var s = new ServiceLocator();
            s.Register<IAudio>(new __Audio("B"));
            var o1 = s.Override<IAudio>(new __Audio("A1"));
            var o2 = s.Override<IAudio>(new __Audio("A2"));
            o1.Dispose();
            string e = Expect(s, "A1, A2 시작 → A1 먼저 해제", "A2"); if (e != null) return e;
            o2.Dispose();
            e = Expect(s, "이어서 A2 해제 (이미 끝난 A1 이 되살아나면 안 됨)", "B"); if (e != null) return e;
            var p1 = s.Override<IAudio>(new __Audio("C1"));
            var p2 = s.Override<IAudio>(new __Audio("C2"));
            var p3 = s.Override<IAudio>(new __Audio("C3"));
            p2.Dispose(); e = Expect(s, "C1~C3 시작 → C2 해제", "C3"); if (e != null) return e;
            p3.Dispose(); e = Expect(s, "이어서 C3 해제", "C1"); if (e != null) return e;
            p1.Dispose(); return Expect(s, "이어서 C1 해제", "B");
        });

        Run("dispose-twice-same-instance", () =>
        {
            var s = new ServiceLocator();
            s.Register<IAudio>(new __Audio("B"));
            var o1 = s.Override<IAudio>(new __Audio("A"));
            var o2 = s.Override<IAudio>(new __Audio("X"));
            o2.Dispose(); o2.Dispose();
            string e = Expect(s, "A, X 시작 → X 를 두 번 Dispose", "A"); if (e != null) return e;
            o1.Dispose(); o1.Dispose();
            e = Expect(s, "A 도 두 번 Dispose", "B"); if (e != null) return e;
            var shared = new __Audio("S");
            var q1 = s.Override<IAudio>(shared);
            var q2 = s.Override<IAudio>(new __Audio("M"));
            var q3 = s.Override<IAudio>(shared);
            q3.Dispose(); e = Expect(s, "S, M, S(같은 인스턴스) 시작 → 세 번째 범위 해제", "M"); if (e != null) return e;
            q2.Dispose(); e = Expect(s, "이어서 M 해제", "S"); if (e != null) return e;
            q1.Dispose(); return Expect(s, "이어서 첫 S 해제", "B");
        });

        Run("register-during-override", () =>
        {
            var s = new ServiceLocator();
            s.Register<IAudio>(new __Audio("B1"));
            var o = s.Override<IAudio>(new __Audio("F"));
            s.Register<IAudio>(new __Audio("B2"));
            string e = Expect(s, "Override(F) 중 Register(B2)", "F"); if (e != null) return e;
            o.Dispose(); e = Expect(s, "F 해제 (새 기본값이어야 함)", "B2"); if (e != null) return e;
            var t = new ServiceLocator();
            var only = t.Override<IAudio>(new __Audio("T"));
            e = Expect(t, "기본 등록 없이 Override(T)", "T"); if (e != null) return e;
            only.Dispose();
            return Expect(t, "T 해제 (기본 등록이 없음)", "(없음)");
        });

        Run("types-independent", () =>
        {
            var s = new ServiceLocator();
            var baseN = new __Analytics("NB");
            s.Register<IAudio>(new __Audio("B"));
            s.Register<IAnalytics>(baseN);
            var oa = s.Override<IAudio>(new __Audio("FA"));
            var fn = new __Analytics("FN");
            var on = s.Override<IAnalytics>(fn);
            oa.Dispose();
            string e = Expect(s, "IAudio, IAnalytics 순으로 오버라이드 → IAudio 해제", "B"); if (e != null) return e;
            if (!object.ReferenceEquals(s.Get<IAnalytics>(), fn)) return "IAudio 범위를 해제했더니 IAnalytics 오버라이드가 사라짐";
            var oa2 = s.Override<IAudio>(new __Audio("FA2"));
            on.Dispose();
            if (!object.ReferenceEquals(s.Get<IAnalytics>(), baseN)) return "IAnalytics 범위 해제 후 기본값으로 돌아가지 않음";
            e = Expect(s, "IAnalytics 해제 (IAudio 의 FA2 는 남아야 함)", "FA2"); if (e != null) return e;
            oa2.Dispose(); return Expect(s, "FA2 해제", "B");
        });

        Run("consumer-hidden-dependency", () =>
        {
            var spawner = new WaveSpawner();   // 무엇이 필요한지 시그니처에 드러나지 않는다
            try { spawner.StartWave(1); return "아무것도 등록하지 않았는데 StartWave 가 성공함"; }
            catch (System.InvalidOperationException e) { if (!e.Message.Contains("IAudio")) return "첫 실패 메시지에 IAudio 가 없음: " + e.Message; }
            var audio = new __Audio("FA");
            var analytics = new __Analytics("FN");
            using (Game.Services.Override<IAudio>(audio))
            {
                try { spawner.StartWave(2); return "IAnalytics 없이 StartWave 가 성공함"; }
                catch (System.InvalidOperationException e) { if (!e.Message.Contains("IAnalytics")) return "두 번째 실패 메시지에 IAnalytics 가 없음: " + e.Message; }
                if (audio.Log.Count != 1) return "IAnalytics 에서 실패하기 전에 효과음이 재생되어 있어야 함(재생 " + audio.Log.Count + "회)";
                using (Game.Services.Override<IAnalytics>(analytics))
                {
                    spawner.StartWave(3);
                }
            }
            if (string.Join(",", audio.Log) != "wave_start,wave_start" || string.Join(",", analytics.Log) != "wave_3")
                return "가짜 서비스 기록이 다름: audio=" + string.Join(",", audio.Log) + " analytics=" + string.Join(",", analytics.Log);
            IAudio a; IAnalytics n;
            if (Game.Services.TryGet<IAudio>(out a) || Game.Services.TryGet<IAnalytics>(out n)) return "using 블록이 끝난 뒤에도 전역 로케이터에 가짜가 남아 있음";
            return null;
        });
    }
}

