using System;
using System.Collections.Generic;

public enum BuffKind { Attack, Haste }

public sealed class Buff
{
    public readonly int Id;
    public readonly BuffKind Kind;
    public readonly int PerStack;
    public int Stacks;
    public int RemainingMs;

    public Buff(int id, BuffKind kind, int perStack, int stacks, int durationMs)
    {
        Id = id; Kind = kind; PerStack = perStack; Stacks = stacks; RemainingMs = durationMs;
    }

    public int Value { get { return PerStack * Stacks; } }
}

// 캐릭터 시트: 기본 데이터가 바뀌면 플래그만 세우고, 파생 스탯은 읽을 때 다시 계산한다.
public sealed class CharacterSheet
{
    private int _strength, _weaponAttack, _baseMoveSpeed;
    private readonly List<Buff> _buffs = new List<Buff>();

    private bool _attackDirty = true, _speedDirty = true;
    private int _attackCache, _speedCache;

    // 프로파일러 카운터: 계산 함수가 실제로 실행된 횟수
    public int AttackRecalcCount { get; private set; }
    public int MoveSpeedRecalcCount { get; private set; }

    public CharacterSheet(int strength, int weaponAttack, int baseMoveSpeed)
    {
        _strength = strength; _weaponAttack = weaponAttack; _baseMoveSpeed = baseMoveSpeed;
    }

    public int Strength
    {
        get { return _strength; }
        set { _strength = value; _speedDirty = true; }
    }

    public int WeaponAttack
    {
        get { return _weaponAttack; }
        set { _weaponAttack = value; _attackDirty = true; }
    }

    public int BaseMoveSpeed
    {
        get { return _baseMoveSpeed; }
        set { _baseMoveSpeed = value; _speedDirty = true; }
    }

    public int BuffCount { get { return _buffs.Count; } }

    public void AddBuff(int id, BuffKind kind, int perStack, int stacks, int durationMs)
    {
        _buffs.Add(new Buff(id, kind, perStack, stacks, durationMs));
        MarkDirty(kind);
    }

    // 같은 버프를 다시 맞으면 스택 수와 남은 시간을 새로 정한다. 그런 id 가 없으면 false.
    public bool RefreshBuff(int id, int stacks, int durationMs)
    {
        Buff b = Find(id);
        if (b == null) return false;
        b.Stacks = stacks;
        b.RemainingMs = durationMs;
        return true;
    }

    // 디스펠: 버프를 즉시 제거한다. 그런 id 가 없으면 false.
    public bool RemoveBuff(int id)
    {
        Buff b = Find(id);
        if (b == null) return false;
        _buffs.Remove(b);
        MarkDirty(b.Kind);
        return true;
    }

    // 매 프레임 호출. 남은 시간이 0 이하가 된 버프는 이 Tick 에서 만료된다.
    public void Tick(int dtMs)
    {
        for (int i = _buffs.Count - 1; i >= 0; i--)
        {
            _buffs[i].RemainingMs -= dtMs;
            if (_buffs[i].RemainingMs <= 0) _buffs.RemoveAt(i);
        }
        _attackDirty = true;
        _speedDirty = true;
    }

    public int AttackPower
    {
        get
        {
            if (_attackDirty) { _attackCache = ComputeAttack(); _attackDirty = false; }
            return _attackCache;
        }
    }

    public int MoveSpeed
    {
        get
        {
            if (_speedDirty) { _speedCache = ComputeMoveSpeed(); _speedDirty = false; }
            return _speedCache;
        }
    }

    // 공격 버프는 중첩되지 않는다: 가장 큰 것 하나만 더한다.
    private int ComputeAttack()
    {
        AttackRecalcCount++;
        return _strength * 2 + _weaponAttack + StrongestBuff(BuffKind.Attack);
    }

    // 이동 속도 버프도 가장 큰 것 하나만 더한다.
    private int ComputeMoveSpeed()
    {
        MoveSpeedRecalcCount++;
        return _baseMoveSpeed + StrongestBuff(BuffKind.Haste);
    }

    private int StrongestBuff(BuffKind kind)
    {
        int best = 0;
        for (int i = 0; i < _buffs.Count; i++)
            if (_buffs[i].Kind == kind && _buffs[i].Value > best) best = _buffs[i].Value;
        return best;
    }

    private void MarkDirty(BuffKind kind)
    {
        if (kind == BuffKind.Attack) _attackDirty = true;
        else _speedDirty = true;
    }

    private Buff Find(int id)
    {
        for (int i = 0; i < _buffs.Count; i++)
            if (_buffs[i].Id == id) return _buffs[i];
        return null;
    }
}

