public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name + " " + e.Message; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static string Val(string what, int expected, int got)
    {
        return expected == got ? null : what + ": 기대 " + expected + " / 결과 " + got;
    }

    // 읽기 전후의 계산 횟수 차이를 확인한다
    static string Reads(CharacterSheet s, string step, int atk, int spd, int atkRecalc, int spdRecalc)
    {
        int a0 = s.AttackRecalcCount, m0 = s.MoveSpeedRecalcCount;
        string e = Val(step + " 뒤 AttackPower", atk, s.AttackPower) ?? Val(step + " 뒤 MoveSpeed", spd, s.MoveSpeed);
        if (e != null) return e;
        int da = s.AttackRecalcCount - a0, dm = s.MoveSpeedRecalcCount - m0;
        if (da != atkRecalc) return step + " 뒤 AttackPower 계산 횟수: 기대 " + atkRecalc + " / 결과 " + da;
        if (dm != spdRecalc) return step + " 뒤 MoveSpeed 계산 횟수: 기대 " + spdRecalc + " / 결과 " + dm;
        // 바로 다시 읽으면 계산하지 않아야 한다
        int a1 = s.AttackRecalcCount, m1 = s.MoveSpeedRecalcCount;
        int x = s.AttackPower + s.MoveSpeed;
        if (s.AttackRecalcCount != a1 || s.MoveSpeedRecalcCount != m1) return step + " 뒤 바뀐 것 없이 다시 읽었는데 재계산함";
        return null;
    }

    public static void Main()
    {
        Run("initial-and-clean-read", () =>
        {
            var s = new CharacterSheet(10, 7, 300);
            return Reads(s, "생성", 27, 300, 1, 1)
                ?? Reads(s, "아무것도 안 바꾸고 한 번 더", 27, 300, 0, 0);
        });

        Run("strength-changes-attack", () =>
        {
            var s = new CharacterSheet(10, 7, 300);
            string e = Reads(s, "생성", 27, 300, 1, 1); if (e != null) return e;
            s.Strength = 15;
            e = Reads(s, "Strength 10 → 15 (Tick 없음)", 37, 300, 1, 0); if (e != null) return e;
            s.WeaponAttack = 20;
            return Reads(s, "WeaponAttack 7 → 20", 50, 300, 1, 0);
        });

        Run("refresh-stacks-changes-value", () =>
        {
            var s = new CharacterSheet(10, 0, 300);
            s.AddBuff(1, BuffKind.Attack, 5, 1, 10000);
            string e = Reads(s, "공격 버프 5 x 1스택", 25, 300, 1, 1); if (e != null) return e;
            if (!s.RefreshBuff(1, 3, 10000)) return "있는 버프의 RefreshBuff 가 false";
            e = Reads(s, "RefreshBuff(스택 1 → 3, Tick 없음)", 35, 300, 1, 0); if (e != null) return e;
            s.AddBuff(2, BuffKind.Haste, 40, 1, 10000);
            e = Reads(s, "이동 버프 40", 35, 340, 0, 1); if (e != null) return e;
            if (!s.RefreshBuff(2, 2, 10000)) return "있는 버프의 RefreshBuff 가 false";
            e = Reads(s, "이동 버프 스택 1 → 2", 35, 380, 0, 1); if (e != null) return e;
            if (s.RefreshBuff(99, 5, 1000)) return "없는 id 의 RefreshBuff 가 true";
            return Reads(s, "없는 id RefreshBuff", 35, 380, 0, 0);
        });

        Run("tick-without-expiry-no-recalc", () =>
        {
            var s = new CharacterSheet(10, 7, 300);
            s.AddBuff(1, BuffKind.Attack, 6, 1, 5000);
            s.AddBuff(2, BuffKind.Haste, 50, 1, 5000);
            string e = Reads(s, "버프 두 개", 33, 350, 1, 1); if (e != null) return e;
            int a0 = s.AttackRecalcCount, m0 = s.MoveSpeedRecalcCount;
            for (int f = 0; f < 120; f++)
            {
                s.Tick(16);   // HUD 가 매 프레임 두 값을 읽는다
                if (s.AttackPower != 33 || s.MoveSpeed != 350) return (f + 1) + "프레임째 값이 바뀜(만료 전)";
            }
            if (s.AttackRecalcCount != a0 || s.MoveSpeedRecalcCount != m0)
                return "만료되는 버프가 없는 120프레임 동안 재계산 Attack " + (s.AttackRecalcCount - a0) + "회, MoveSpeed " + (s.MoveSpeedRecalcCount - m0) + "회 (기대 0, 0)";
            return null;
        });

        Run("tick-expiry-only-its-kind", () =>
        {
            var s = new CharacterSheet(10, 0, 300);
            s.AddBuff(1, BuffKind.Attack, 8, 1, 100);
            s.AddBuff(2, BuffKind.Attack, 3, 1, 5000);
            s.AddBuff(3, BuffKind.Haste, 60, 1, 32);
            string e = Reads(s, "버프 세 개", 28, 360, 1, 1); if (e != null) return e;
            s.Tick(16);
            e = Reads(s, "16ms", 28, 360, 0, 0); if (e != null) return e;
            s.Tick(16);
            e = Reads(s, "32ms (이동 버프의 남은 시간이 정확히 0 → 만료)", 28, 300, 0, 1); if (e != null) return e;
            for (int f = 0; f < 4; f++) s.Tick(16);
            e = Reads(s, "96ms", 28, 300, 0, 0); if (e != null) return e;
            s.Tick(16);
            e = Reads(s, "112ms (가장 큰 공격 버프 만료 → 다음으로 큰 버프)", 23, 300, 1, 0); if (e != null) return e;
            if (s.BuffCount != 1) return "만료 뒤 BuffCount 기대 1 / 결과 " + s.BuffCount;
            if (!s.RemoveBuff(2)) return "있는 버프의 RemoveBuff 가 false";
            return Reads(s, "디스펠", 20, 300, 1, 0);
        });

        Run("batch-changes-one-recalc", () =>
        {
            var s = new CharacterSheet(10, 7, 300);
            string e = Reads(s, "생성", 27, 300, 1, 1); if (e != null) return e;
            int a0 = s.AttackRecalcCount;
            s.Strength = 12; s.WeaponAttack = 9; s.AddBuff(1, BuffKind.Attack, 4, 1, 1000);
            s.RefreshBuff(1, 2, 1000); s.Strength = 14; s.AddBuff(2, BuffKind.Attack, 1, 1, 1000); s.RemoveBuff(2);
            if (s.AttackRecalcCount != a0) return "값을 읽기 전에 계산이 " + (s.AttackRecalcCount - a0) + "회 일어남 (읽을 때 한 번이어야 함)";
            return Reads(s, "읽지 않고 입력 7번 변경", 45, 300, 1, 0);
        });

        Run("fine-grained-flags", () =>
        {
            var s = new CharacterSheet(10, 7, 300);
            string e = Reads(s, "생성", 27, 300, 1, 1); if (e != null) return e;
            s.BaseMoveSpeed = 320;
            e = Reads(s, "BaseMoveSpeed 변경", 27, 320, 0, 1); if (e != null) return e;
            s.Strength = 11;
            e = Reads(s, "Strength 변경", 29, 320, 1, 0); if (e != null) return e;
            s.AddBuff(5, BuffKind.Haste, 10, 1, 48);
            e = Reads(s, "이동 버프 추가", 29, 330, 0, 1); if (e != null) return e;
            s.Tick(16); s.Tick(16); s.Tick(16);
            e = Reads(s, "이동 버프 만료", 29, 320, 0, 1); if (e != null) return e;
            s.AddBuff(6, BuffKind.Attack, 2, 1, 1000);
            e = Reads(s, "공격 버프 추가", 31, 320, 1, 0); if (e != null) return e;
            s.RemoveBuff(6);
            return Reads(s, "공격 버프 디스펠", 29, 320, 1, 0);
        });

        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(2026);
            for (int run = 0; run < 40; run++)
            {
                int str = rng.Next(1, 30), wpn = rng.Next(0, 50), spd = rng.Next(200, 400);
                var s = new CharacterSheet(str, wpn, spd);
                var ids = new System.Collections.Generic.List<int>();
                var kind = new System.Collections.Generic.Dictionary<int, BuffKind>();
                var per = new System.Collections.Generic.Dictionary<int, int>();
                var stacks = new System.Collections.Generic.Dictionary<int, int>();
                var left = new System.Collections.Generic.Dictionary<int, int>();
                int nextId = 1;
                for (int k = 0; k < 200; k++)
                {
                    int c = rng.Next(100);
                    if (c < 10) { str = rng.Next(1, 30); s.Strength = str; }
                    else if (c < 18) { wpn = rng.Next(0, 50); s.WeaponAttack = wpn; }
                    else if (c < 25) { spd = rng.Next(200, 400); s.BaseMoveSpeed = spd; }
                    else if (c < 45)
                    {
                        int id = nextId++; BuffKind bk = rng.Next(2) == 0 ? BuffKind.Attack : BuffKind.Haste;
                        int p = rng.Next(1, 20), st = rng.Next(1, 4), d = rng.Next(1, 40) * 16;
                        s.AddBuff(id, bk, p, st, d); ids.Add(id); kind[id] = bk; per[id] = p; stacks[id] = st; left[id] = d;
                    }
                    else if (c < 60 && ids.Count > 0)
                    {
                        int id = ids[rng.Next(ids.Count)]; int st = rng.Next(1, 5), d = rng.Next(1, 40) * 16;
                        s.RefreshBuff(id, st, d); stacks[id] = st; left[id] = d;
                    }
                    else if (c < 66 && ids.Count > 0)
                    {
                        int id = ids[rng.Next(ids.Count)]; s.RemoveBuff(id); ids.Remove(id);
                    }
                    else
                    {
                        s.Tick(16);
                        for (int i = ids.Count - 1; i >= 0; i--) { left[ids[i]] -= 16; if (left[ids[i]] <= 0) ids.RemoveAt(i); }
                    }
                    if (rng.Next(3) == 0) continue;   // 매번 읽지는 않는다
                    int bestA = 0, bestH = 0;
                    foreach (int id in ids)
                    {
                        int v = per[id] * stacks[id];
                        if (kind[id] == BuffKind.Attack) { if (v > bestA) bestA = v; } else if (v > bestH) bestH = v;
                    }
                    int ea = str * 2 + wpn + bestA, es = spd + bestH;
                    if (s.AttackPower != ea || s.MoveSpeed != es)
                        return "무작위 " + run + "회차 " + k + "번째 연산 뒤: 기대 공격 " + ea + " 이동 " + es + " / 결과 공격 " + s.AttackPower + " 이동 " + s.MoveSpeed;
                    if (s.BuffCount != ids.Count) return "무작위 " + run + "회차 " + k + "번째: BuffCount 기대 " + ids.Count + " / 결과 " + s.BuffCount;
                }
            }
            return null;
        });
    }
}

