problems.solutionCode:
using System;
using System.Collections.Generic;

// 2D 씬 그래프의 노드. 로컬 변환 = 부모 기준 위치(X, Y)와 균일 스케일.
// 월드 값: 루트는 로컬과 같고, 자식은
//   WorldScale = parent.WorldScale * LocalScale
//   WorldX     = parent.WorldX + parent.WorldScale * LocalX   (Y 도 같은 식)
//
// 불변식: 어떤 노드가 dirty 면 그 자손도 모두 dirty 다.
//   - 그래서 깨끗한 노드는 조상도 모두 깨끗하다 → 깨끗한 노드의 읽기는 O(1), 조상을 볼 필요가 없다.
//   - 표시할 때 이미 dirty 인 노드에서 멈춰도 된다 → 각 노드는 다시 계산될 때까지 한 번만 표시된다.
public sealed class SceneNode
{
    private readonly List<SceneNode> _children = new List<SceneNode>();
    private SceneNode _parent;
    private double _localX, _localY, _localScale = 1.0;
    private double _worldX, _worldY, _worldScale;
    private bool _dirty = true;          // 태어날 때는 아직 계산한 적이 없다
    private int _recalcCount;

    public SceneNode(string name)
    {
        Name = name;
    }

    public string Name { get; }
    public SceneNode Parent { get { return _parent; } }
    public int ChildCount { get { return _children.Count; } }

    public double LocalX { get { return _localX; } }
    public double LocalY { get { return _localY; } }
    public double LocalScale { get { return _localScale; } }

    public void SetLocal(double x, double y, double scale)
    {
        if (!(scale > 0.0) || double.IsInfinity(scale)) throw new ArgumentOutOfRangeException(nameof(scale));
        _localX = x; _localY = y; _localScale = scale;
        MarkSubtreeDirty();                   // 계산은 하지 않는다. 읽을 때 한다.
    }

    public void SetParent(SceneNode parent, bool worldPositionStays)
    {
        for (SceneNode p = parent; p != null; p = p._parent)
            if (p == this) throw new InvalidOperationException("자기 자신이나 자손을 부모로 둘 수 없습니다: " + Name);

        double wx = 0, wy = 0, ws = 1;
        double px = 0, py = 0, ps = 1;
        if (worldPositionStays)
        {
            // 링크를 바꾸기 전에 현재 월드 값과 새 부모의 월드 값을 읽는다(읽기 규칙대로 필요하면 계산된다).
            wx = WorldX; wy = WorldY; ws = WorldScale;
            if (parent != null) { px = parent.WorldX; py = parent.WorldY; ps = parent.WorldScale; }
        }

        if (_parent != null) _parent._children.Remove(this);
        _parent = parent;
        if (parent != null) parent._children.Add(this);

        if (worldPositionStays)
        {
            // 월드 = 부모월드 + 부모스케일 * 로컬  →  로컬 = (월드 - 부모월드) / 부모스케일
            _localX = (wx - px) / ps;
            _localY = (wy - py) / ps;
            _localScale = ws / ps;
        }
        MarkSubtreeDirty();
    }

    public double WorldX { get { EnsureClean(); return _worldX; } }
    public double WorldY { get { EnsureClean(); return _worldY; } }
    public double WorldScale { get { EnsureClean(); return _worldScale; } }

    public int WorldRecalcCount { get { return _recalcCount; } }

    private void MarkSubtreeDirty()
    {
        if (_dirty) return;                   // 불변식: 자손도 이미 dirty
        _dirty = true;
        for (int i = 0; i < _children.Count; i++) _children[i].MarkSubtreeDirty();
    }

    // dirty 인 조상만 위에서부터 다시 계산한다(첫 번째 깨끗한 조상에서 멈춘다).
    private void EnsureClean()
    {
        if (!_dirty) return;
        if (_parent != null) _parent.EnsureClean();
        if (_parent == null)
        {
            _worldX = _localX; _worldY = _localY; _worldScale = _localScale;
        }
        else
        {
            double s = _parent._worldScale;
            _worldScale = s * _localScale;
            _worldX = _parent._worldX + s * _localX;
            _worldY = _parent._worldY + s * _localY;
        }
        _dirty = false;
        _recalcCount++;
    }
}

