{{USER_CODE}}

public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name + " " + e.Message; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static string F(double v) { return v.ToString("0.######", System.Globalization.CultureInfo.InvariantCulture); }
    static string W(SceneNode n) { return "(" + F(n.WorldX) + ", " + F(n.WorldY) + ", " + F(n.WorldScale) + ")"; }

    static SceneNode N(string name, double x, double y, double s, SceneNode parent)
    {
        var n = new SceneNode(name);
        n.SetLocal(x, y, s);
        if (parent != null) n.SetParent(parent, false);
        return n;
    }

    // 노드 하나를 읽고 값과, 그 읽기 동안 늘어난 노드별 재계산 횟수를 확인한다.
    static string Read(string step, SceneNode target, string world, SceneNode[] all, string recalc)
    {
        int[] before = new int[all.Length];
        for (int i = 0; i < all.Length; i++) before[i] = all[i].WorldRecalcCount;
        string got = W(target);
        var sb = new System.Text.StringBuilder();
        for (int i = 0; i < all.Length; i++)
        {
            int d = all[i].WorldRecalcCount - before[i];
            if (d != 0) sb.Append(sb.Length == 0 ? "" : " ").Append(all[i].Name).Append(d);
        }
        string counts = sb.Length == 0 ? "-" : sb.ToString();
        if (got != world) return step + ": " + target.Name + " 월드 기대 " + world + " / 결과 " + got;
        if (counts != recalc) return step + ": " + target.Name + " 을 읽는 동안 재계산 기대 [" + recalc + "] / 결과 [" + counts + "]";
        return null;
    }

    static int Total(SceneNode[] all) { int t = 0; foreach (var n in all) t += n.WorldRecalcCount; return t; }

    public static void Main()
    {
        Run("world-formula-first-read", () =>
        {
            var root = N("root", 100, 0, 2, null);
            var a = N("a", 0, 10, 1, root);
            var b = N("b", 1, 2, 0.5, a);
            var all = new[] { root, a, b };
            if (b.Parent != a || a.ChildCount != 1 || root.ChildCount != 1) return "Parent / ChildCount 가 틀림";
            if (Total(all) != 0) return "아무것도 읽기 전에 월드 계산이 " + Total(all) + "회 일어남";
            return Read("첫 읽기", b, "(102, 24, 1)", all, "root1 a1 b1")
                ?? Read("다시 읽기", b, "(102, 24, 1)", all, "-")
                ?? Read("중간 노드", a, "(100, 20, 2)", all, "-");
        });

        Run("gpp-four-moves-one-each", () =>
        {
            var ship = N("ship", 100, 0, 2, null);
            var nest = N("nest", 0, 10, 1, ship);
            var pirate = N("pirate", 1, 2, 0.5, nest);
            var parrot = N("parrot", 0.5, 1, 1, pirate);
            var all = new[] { ship, nest, pirate, parrot };
            string e = Read("첫 읽기", parrot, "(102.5, 25, 1)", all, "ship1 nest1 pirate1 parrot1"); if (e != null) return e;
            int t0 = Total(all);
            ship.SetLocal(50, 5, 1); nest.SetLocal(2, 8, 3); pirate.SetLocal(1, 0, 1); parrot.SetLocal(0, 1, 2);
            if (Total(all) != t0) return "SetLocal 네 번 동안 월드 계산이 " + (Total(all) - t0) + "회 일어남 (읽을 때 해야 함)";
            return Read("네 노드를 모두 움직인 뒤", parrot, "(55, 16, 6)", all, "ship1 nest1 pirate1 parrot1")
                ?? Read("이어서 nest", nest, "(52, 13, 3)", all, "-");
        });

        Run("parent-move-all-children", () =>
        {
            var p = N("P", 0, 0, 1, null);
            var c1 = N("C1", 10, 0, 1, p);
            var c2 = N("C2", 0, 10, 1, p);
            var g = N("G", 1, 1, 1, c1);
            var all = new[] { p, c1, c2, g };
            W(g); W(c2);
            p.SetLocal(5, 5, 2);
            return Read("P 이동 뒤 C2", c2, "(5, 25, 2)", all, "P1 C21")
                ?? Read("이어서 G (P 는 이미 계산됨, C1 은 아직)", g, "(27, 7, 2)", all, "C11 G1")
                ?? Read("이어서 C1", c1, "(25, 5, 2)", all, "-")
                ?? Read("자식만 이동: G 로컬 변경 뒤 G", Do(() => g.SetLocal(2, 0, 1), g), "(29, 5, 2)", all, "G1");
        });

        Run("clean-read-isolation", () =>
        {
            var r1 = N("R1", 0, 0, 1, null); var a = N("A", 1, 0, 1, r1);
            var r2 = N("R2", 100, 0, 1, null); var b = N("B", 0, 1, 1, r2); var c = N("C", 0, 1, 1, b);
            var all = new[] { r1, a, r2, b, c };
            W(a); W(c);
            r1.SetLocal(3, 0, 1);
            string e = Read("R1 이동 뒤 다른 트리의 C", c, "(100, 2, 1)", all, "-"); if (e != null) return e;
            for (int i = 0; i < 50; i++) { W(c); W(b); W(r2); }
            e = Read("깨끗한 노드 150번 읽은 뒤", c, "(100, 2, 1)", all, "-"); if (e != null) return e;
            return Read("R1 의 자식 A", a, "(4, 0, 1)", all, "R11 A1");
        });

        Run("reparent-keep-local", () =>
        {
            var oldP = N("Old", 10, 0, 1, null);
            var newP = N("New", 0, 100, 2, null);
            var n = N("N", 1, 1, 1, oldP);
            var kid = N("K", 0, 1, 1, n);
            var all = new[] { oldP, newP, n, kid };
            W(kid); W(newP);
            n.SetParent(newP, false);
            if (n.Parent != newP || oldP.ChildCount != 0 || newP.ChildCount != 1) return "SetParent 뒤 Parent / ChildCount 가 틀림";
            if (n.LocalX != 1 || n.LocalY != 1 || n.LocalScale != 1) return "worldPositionStays=false 인데 로컬 값이 바뀜";
            string e = Read("New 아래로 옮긴 뒤 K", kid, "(2, 104, 2)", all, "N1 K1"); if (e != null) return e;
            oldP.SetLocal(-50, -50, 3);
            e = Read("예전 부모 Old 이동 뒤 K", kid, "(2, 104, 2)", all, "-"); if (e != null) return e;
            newP.SetLocal(0, 0, 1);
            e = Read("새 부모 New 이동 뒤 K", kid, "(1, 2, 1)", all, "New1 N1 K1"); if (e != null) return e;
            n.SetParent(null, false);
            return Read("루트로 떼어 낸 뒤 K", kid, "(1, 2, 1)", all, "N1 K1");
        });

        Run("reparent-world-stays", () =>
        {
            var oldP = N("Old", 10, 0, 1, null);
            var newP = N("New", 4, 100, 2, null);
            var n = N("N", 2, 6, 3, oldP);
            var kid = N("K", 1, 0, 1, n);
            var all = new[] { oldP, newP, n, kid };
            W(kid); W(newP);
            n.SetParent(newP, true);
            string lc = "(" + F(n.LocalX) + ", " + F(n.LocalY) + ", " + F(n.LocalScale) + ")";
            if (lc != "(4, -47, 1.5)") return "worldPositionStays=true 뒤 N 로컬 기대 (4, -47, 1.5) / 결과 " + lc;
            string e = Read("월드 유지 이동 뒤 N", n, "(12, 6, 3)", all, "N1"); if (e != null) return e;
            e = Read("이어서 K", kid, "(15, 6, 3)", all, "K1"); if (e != null) return e;
            newP.SetLocal(4, 0, 2);
            e = Read("새 부모 이동 뒤 K", kid, "(15, -94, 3)", all, "New1 N1 K1"); if (e != null) return e;
            n.SetParent(null, true);
            lc = "(" + F(n.LocalX) + ", " + F(n.LocalY) + ", " + F(n.LocalScale) + ")";
            if (lc != "(12, -94, 3)") return "루트로 떼어 낼 때(월드 유지) N 로컬 기대 (12, -94, 3) / 결과 " + lc;
            return Read("루트로 떼어 낸 뒤 K", kid, "(15, -94, 3)", all, "N1 K1");
        });

        Run("reject-cycle-and-bad-scale", () =>
        {
            var a = N("A", 1, 0, 1, null); var b = N("B", 1, 0, 1, a); var c = N("C", 1, 0, 1, b);
            var all = new[] { a, b, c };
            W(c);
            foreach (var bad in new[] { a, c })
            {
                try { a.SetParent(bad, false); return "A.SetParent(" + bad.Name + ") 가 예외 없이 통과함"; }
                catch (System.InvalidOperationException) { }
            }
            try { b.SetParent(c, true); return "B.SetParent(C) (자손) 가 예외 없이 통과함"; }
            catch (System.InvalidOperationException) { }
            if (a.Parent != null || b.Parent != a || c.Parent != b || a.ChildCount != 1 || b.ChildCount != 1) return "거절된 SetParent 가 구조를 바꿈";
            foreach (double s in new[] { 0.0, -2.0, double.NaN, double.PositiveInfinity })
            {
                try { b.SetLocal(9, 9, s); return "scale " + s + " 이 예외 없이 통과함"; }
                catch (System.ArgumentOutOfRangeException) { }
            }
            if (b.LocalX != 1 || b.LocalScale != 1) return "거절된 SetLocal 이 로컬 값을 바꿈";
            return Read("거절된 호출들 뒤 C", c, "(3, 0, 1)", all, "-");
        });

        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(7);
            for (int run = 0; run < 30; run++)
            {
                int n = 12;
                var nodes = new SceneNode[n];
                int[] par = new int[n]; double[] lx = new double[n], ly = new double[n], ls = new double[n];
                double[] scales = { 0.5, 1, 2 };
                for (int i = 0; i < n; i++) { nodes[i] = new SceneNode("n" + i); par[i] = -1; lx[i] = 0; ly[i] = 0; ls[i] = 1; }
                System.Func<int, double[]> world = null;
                world = i => { if (par[i] < 0) return new[] { lx[i], ly[i], ls[i] }; var p = world(par[i]); return new[] { p[0] + p[2] * lx[i], p[1] + p[2] * ly[i], p[2] * ls[i] }; };
                System.Func<int, int, bool> isAnc = (anc, i) => { for (int q = i; q >= 0; q = par[q]) if (q == anc) return true; return false; };
                for (int k = 0; k < 150; k++)
                {
                    int i = rng.Next(n), c = rng.Next(100);
                    if (c < 35)
                    {
                        double x = rng.Next(-20, 21), y = rng.Next(-20, 21), s = scales[rng.Next(3)];
                        nodes[i].SetLocal(x, y, s); lx[i] = x; ly[i] = y; ls[i] = s;
                    }
                    else if (c < 65)
                    {
                        int j = rng.Next(n + 1) - 1;   // -1 이면 루트로
                        if (j >= 0 && isAnc(i, j)) continue;
                        bool stays = rng.Next(2) == 0;
                        if (stays)
                        {
                            var w = world(i);
                            if (j < 0) { lx[i] = w[0]; ly[i] = w[1]; ls[i] = w[2]; }
                            else { var pw = world(j); lx[i] = (w[0] - pw[0]) / pw[2]; ly[i] = (w[1] - pw[1]) / pw[2]; ls[i] = w[2] / pw[2]; }
                        }
                        nodes[i].SetParent(j < 0 ? null : nodes[j], stays); par[i] = j;
                    }
                    else
                    {
                        var w = world(i);
                        double gx = nodes[i].WorldX, gy = nodes[i].WorldY, gs = nodes[i].WorldScale;
                        double tol = 1e-6 * (1 + System.Math.Abs(w[0]) + System.Math.Abs(w[1]) + System.Math.Abs(w[2]));
                        if (System.Math.Abs(gx - w[0]) > tol || System.Math.Abs(gy - w[1]) > tol || System.Math.Abs(gs - w[2]) > tol)
                            return "무작위 " + run + "회차 " + k + "번째: n" + i + " 월드 기대 (" + F(w[0]) + ", " + F(w[1]) + ", " + F(w[2]) + ") / 결과 (" + F(gx) + ", " + F(gy) + ", " + F(gs) + ")";
                        if ((nodes[i].Parent == null) != (par[i] < 0) || (par[i] >= 0 && nodes[i].Parent != nodes[par[i]])) return "무작위 " + run + "회차 " + k + "번째: n" + i + " 의 Parent 가 틀림";
                    }
                }
            }
            return null;
        });
    }

    static SceneNode Do(System.Action act, SceneNode n) { act(); return n; }
}

