using System;
using System.Collections.Generic;

// 입력 이벤트 하나. 처리한 핸들러가 Consume() 을 부르면 아래 계층으로 내려가지 않는다. (바꾸지 않는다)
public sealed class InputEvent
{
    public InputEvent(string action) { Action = action; }
    public string Action { get; }
    public bool Consumed { get; private set; }
    public void Consume() { Consumed = true; }
}

// 입력 계층 하나(팝업, 인벤토리 창, HUD, 카메라, 캐릭터 조작 ...). (바꾸지 않는다)
public interface IInputHandler
{
    void Handle(InputEvent e);
}

public sealed class InputRouter
{
    private sealed class Entry
    {
        public IInputHandler Handler;
        public int Priority;
        public bool Removed;              // Dispatch 도중 제거되면 아직 차례가 안 온 경우 건너뛴다
    }

    // 항상 호출 순서대로 정렬되어 있다: priority 내림차순, 같으면 나중에 추가된 것이 앞.
    private readonly List<Entry> _chain = new List<Entry>();
    // Dispatch 가 시작될 때의 체인을 담아 두는 재사용 버퍼(도중의 Add 는 여기에 들어오지 않는다).
    private readonly List<Entry> _snapshot = new List<Entry>();

    public int Count { get { return _chain.Count; } }

    public bool Add(IInputHandler handler, int priority)
    {
        if (handler == null) throw new ArgumentNullException(nameof(handler));
        if (IndexOf(handler) >= 0) return false;
        // 같은 priority 중에서는 새 것이 맨 앞: priority 가 "작거나 같은" 첫 항목 앞에 끼운다.
        int i = 0;
        while (i < _chain.Count && _chain[i].Priority > priority) i++;
        _chain.Insert(i, new Entry { Handler = handler, Priority = priority });
        return true;
    }

    public bool Remove(IInputHandler handler)
    {
        if (handler == null) throw new ArgumentNullException(nameof(handler));
        int i = IndexOf(handler);
        if (i < 0) return false;
        _chain[i].Removed = true;
        _chain.RemoveAt(i);
        return true;
    }

    public bool Dispatch(InputEvent e)
    {
        if (e == null) throw new ArgumentNullException(nameof(e));
        if (e.Consumed) return true;            // 이미 누군가 처리한 이벤트

        _snapshot.Clear();
        _snapshot.AddRange(_chain);
        bool consumed = false;
        for (int i = 0; i < _snapshot.Count; i++)
        {
            Entry entry = _snapshot[i];
            if (entry.Removed) continue;        // 이번 Dispatch 도중, 차례가 오기 전에 제거됨
            entry.Handler.Handle(e);
            if (e.Consumed) { consumed = true; break; }   // 아래 계층에는 넘기지 않는다
        }
        _snapshot.Clear();                       // 핸들러 참조를 붙잡고 있지 않는다
        return consumed;
    }

    private int IndexOf(IInputHandler handler)
    {
        for (int i = 0; i < _chain.Count; i++)
            if (ReferenceEquals(_chain[i].Handler, handler)) return i;
        return -1;
    }
}

