// 테스트용 계층: 받은 이벤트를 공용 로그에 남기고, consumes 에 든 동작이면 소비한다. onHandle 로 체인을 바꿀 수 있다.
public sealed class __Layer : IInputHandler
{
    public readonly string Name;
    readonly System.Collections.Generic.List<string> _log;
    public readonly string[] Consumes;
    public System.Action<InputEvent> OnHandle;
    public int Calls;
    public __Layer(string name, System.Collections.Generic.List<string> log, params string[] consumes) { Name = name; _log = log; Consumes = consumes; }
    public void Handle(InputEvent e)
    {
        Calls++;
        _log.Add(Name);
        if (OnHandle != null) OnHandle(e);
        if (System.Array.IndexOf(Consumes, e.Action) >= 0) e.Consume();
    }
}

public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name + " " + e.Message; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    // 이벤트 하나를 보내고 호출 순서와 반환값을 확인한다.
    static string Send(InputRouter r, System.Collections.Generic.List<string> log, string action, string expectedOrder, bool expectedConsumed)
    {
        log.Clear();
        var e = new InputEvent(action);
        bool got = r.Dispatch(e);
        string order = log.Count == 0 ? "-" : string.Join(" ", log);
        if (order != expectedOrder) return "\"" + action + "\" 호출 순서 기대 [" + expectedOrder + "] / 결과 [" + order + "]";
        if (got != expectedConsumed) return "\"" + action + "\" Dispatch 반환값 기대 " + expectedConsumed + " / 결과 " + got;
        if (e.Consumed != expectedConsumed) return "\"" + action + "\" 이벤트의 Consumed 가 반환값과 다름";
        return null;
    }

    public static void Main()
    {
        Run("priority-order", () =>
        {
            var log = new System.Collections.Generic.List<string>();
            var r = new InputRouter();
            r.Add(new __Layer("Player", log), 0);
            r.Add(new __Layer("Popup", log), 300);
            r.Add(new __Layer("HUD", log), 100);
            r.Add(new __Layer("Inventory", log), 200);
            r.Add(new __Layer("Camera", log), -50);
            if (r.Count != 5) return "Count 기대 5 / 결과 " + r.Count;
            return Send(r, log, "Move", "Popup Inventory HUD Player Camera", false);
        });

        Run("consume-stops-lower-layers", () =>
        {
            var log = new System.Collections.Generic.List<string>();
            var r = new InputRouter();
            r.Add(new __Layer("Player", log, "Attack", "Cancel"), 0);
            r.Add(new __Layer("Pause", log, "Cancel"), 50);
            r.Add(new __Layer("Popup", log, "Cancel"), 300);
            r.Add(new __Layer("HUD", log, "Click"), 100);
            return Send(r, log, "Cancel", "Popup", true)
                ?? Send(r, log, "Click", "Popup HUD", true)
                ?? Send(r, log, "Attack", "Popup HUD Pause Player", true)
                ?? Send(r, log, "Move", "Popup HUD Pause Player", false)
                ?? Send(r, log, "Cancel", "Popup", true);
        });

        Run("same-priority-newest-first", () =>
        {
            var log = new System.Collections.Generic.List<string>();
            var r = new InputRouter();
            r.Add(new __Layer("HUD", log), 100);
            r.Add(new __Layer("WinA", log), 200);
            r.Add(new __Layer("WinB", log), 200);
            r.Add(new __Layer("Popup", log), 300);
            r.Add(new __Layer("WinC", log), 200);
            string e = Send(r, log, "Move", "Popup WinC WinB WinA HUD", false);
            if (e != null) return e;
            var big = new InputRouter();
            var expected = new System.Text.StringBuilder();
            for (int i = 0; i < 40; i++) big.Add(new __Layer("W" + i, log), 7);
            for (int i = 39; i >= 0; i--) expected.Append(i == 39 ? "" : " ").Append("W" + i);
            return Send(big, log, "Move", expected.ToString(), false);
        });

        Run("added-during-dispatch-waits", () =>
        {
            var log = new System.Collections.Generic.List<string>();
            var r = new InputRouter();
            var inventory = new __Layer("Inventory", log, "Inventory");
            var hud = new __Layer("HUD", log, "Inventory");
            var player = new __Layer("Player", log);
            var tracker = new __Layer("Tracker", log);          // 소비하지 않는 계층(업적 추적)
            var hint = new __Layer("Hint", log);
            var low = new __Layer("Low", log);
            hud.OnHandle = e => { if (e.Action == "Inventory") r.Add(inventory, 200); };
            inventory.OnHandle = e => { if (e.Action == "Inventory") r.Remove(inventory); };
            bool first = true;
            tracker.OnHandle = e => { if (e.Action == "Move" && first) { first = false; r.Add(hint, 150); r.Add(low, -10); } };
            r.Add(hud, 100); r.Add(player, 0); r.Add(tracker, 400);
            string err = Send(r, log, "Inventory", "Tracker HUD", true);
            if (err != null) return "인벤토리를 여는 입력: " + err;
            err = Send(r, log, "Move", "Tracker Inventory HUD Player", false);
            if (err != null) return "Tracker 가 Hint(150)와 Low(-10)를 추가하는 입력: " + err;
            if (r.Count != 6) return "Dispatch 중 Add 뒤 Count 기대 6 / 결과 " + r.Count;
            err = Send(r, log, "Move", "Tracker Inventory Hint HUD Player Low", false);
            if (err != null) return "다음 입력: " + err;
            err = Send(r, log, "Inventory", "Tracker Inventory", true);
            if (err != null) return "인벤토리를 닫는 입력: " + err;
            return Send(r, log, "Move", "Tracker Hint HUD Player Low", false);
        });

        Run("removed-before-turn-skipped", () =>
        {
            var log = new System.Collections.Generic.List<string>();
            var r = new InputRouter();
            var popup = new __Layer("Popup", log);
            var tooltip = new __Layer("Tooltip", log);
            var hud = new __Layer("HUD", log);
            var player = new __Layer("Player", log, "Confirm");
            popup.OnHandle = e => { if (e.Action == "Confirm") { r.Remove(popup); r.Remove(tooltip); } };
            r.Add(player, 0); r.Add(hud, 100); r.Add(tooltip, 250); r.Add(popup, 300);
            string err = Send(r, log, "Confirm", "Popup HUD Player", true);
            if (err != null) return "팝업이 자신과 툴팁을 닫는 입력: " + err;
            if (r.Count != 2) return "Count 기대 2 / 결과 " + r.Count;
            hud.OnHandle = e => r.Remove(hud);   // 이미 호출된 핸들러가 자신을 제거해도 나머지는 그대로
            err = Send(r, log, "Move", "HUD Player", false);
            if (err != null) return "HUD 가 자기 차례에 자신을 제거: " + err;
            return Send(r, log, "Move", "Player", false);
        });

        Run("add-remove-contract", () =>
        {
            var log = new System.Collections.Generic.List<string>();
            var r = new InputRouter();
            var a = new __Layer("A", log); var b = new __Layer("B", log);
            if (!r.Add(a, 10)) return "처음 Add 가 false";
            if (r.Add(a, 99)) return "이미 등록된 핸들러의 Add 가 true";
            if (r.Count != 1) return "중복 Add 뒤 Count 기대 1 / 결과 " + r.Count;
            if (r.Remove(b)) return "등록되지 않은 핸들러의 Remove 가 true";
            r.Add(b, 5);
            string err = Send(r, log, "Move", "A B", false); if (err != null) return "중복 Add 는 priority 를 바꾸지 않아야 함: " + err;
            if (!r.Remove(a) || r.Remove(a)) return "Remove 반환값이 틀림(첫 번째 true, 두 번째 false)";
            r.Add(a, 1);
            err = Send(r, log, "Move", "B A", false); if (err != null) return "Remove 후 다른 priority 로 다시 Add: " + err;
            try { r.Add(null, 0); return "Add(null) 이 예외 없이 통과함"; } catch (System.ArgumentNullException) { }
            try { r.Remove(null); return "Remove(null) 이 예외 없이 통과함"; } catch (System.ArgumentNullException) { }
            try { r.Dispatch(null); return "Dispatch(null) 이 예외 없이 통과함"; } catch (System.ArgumentNullException) { }
            var done = new InputEvent("Move"); done.Consume();
            log.Clear();
            if (!r.Dispatch(done) || log.Count != 0) return "이미 소비된 이벤트: 아무도 호출하지 않고 true 여야 함";
            return Send(new InputRouter(), log, "Move", "-", false);
        });

        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(99);
            var log = new System.Collections.Generic.List<string>();
            string[] actions = { "Move", "Attack", "Cancel", "Click" };
            for (int run = 0; run < 50; run++)
            {
                var r = new InputRouter();
                var pool = new __Layer[12];
                for (int i = 0; i < pool.Length; i++) pool[i] = new __Layer("L" + i, log, actions[rng.Next(4)], actions[rng.Next(4)]);
                // 기준 모델: (priority, 추가 순번) 목록
                var model = new System.Collections.Generic.List<long[]>();
                long seq = 0;
                for (int k = 0; k < 120; k++)
                {
                    int c = rng.Next(10), idx = rng.Next(pool.Length);
                    int at = model.FindIndex(m => m[0] == idx);
                    if (c < 4)
                    {
                        int pr = rng.Next(4) * 10;
                        bool ok = r.Add(pool[idx], pr);
                        if (ok != (at < 0)) return "무작위 " + run + "회차: Add 반환값이 틀림";
                        if (at < 0) model.Add(new long[] { idx, pr, seq++ });
                    }
                    else if (c < 6)
                    {
                        bool ok = r.Remove(pool[idx]);
                        if (ok != (at >= 0)) return "무작위 " + run + "회차: Remove 반환값이 틀림";
                        if (at >= 0) model.RemoveAt(at);
                    }
                    else
                    {
                        string act = actions[rng.Next(4)];
                        var sorted = new System.Collections.Generic.List<long[]>(model);
                        sorted.Sort((x, y) => x[1] != y[1] ? y[1].CompareTo(x[1]) : y[2].CompareTo(x[2]));
                        var exp = new System.Collections.Generic.List<string>(); bool expConsumed = false;
                        foreach (var m in sorted)
                        {
                            exp.Add("L" + m[0]);
                            if (System.Array.IndexOf(pool[m[0]].Consumes, act) >= 0) { expConsumed = true; break; }
                        }
                        string err = Send(r, log, act, exp.Count == 0 ? "-" : string.Join(" ", exp), expConsumed);
                        if (err != null) return "무작위 " + run + "회차 " + k + "번째: " + err;
                    }
                    if (r.Count != model.Count) return "무작위 " + run + "회차: Count 기대 " + model.Count + " / 결과 " + r.Count;
                }
            }
            return null;
        });
    }
}

