using System;

// 예전 코드(60 FPS 고정 스텝 전제): 90프레임마다 번개 = 1.5초마다.
//     if (++frames == 90) { frames = 0; ShootLightning(); }
// 게임이 가변 dt 루프로 바뀌면서 경과 시간(ms)을 받도록 옮겨 적은 버전이다.
public sealed class LightningStatue
{
    private readonly int _intervalMs;
    private int _timerMs;

    public LightningStatue(int intervalMs)
    {
        _intervalMs = intervalMs;
    }

    public int TotalShots { get; private set; }

    // 이번 프레임에 쏜 번개 수를 돌려준다.
    public int Update(int elapsedMs)
    {
        _timerMs += elapsedMs;
        if (_timerMs >= _intervalMs)
        {
            _timerMs = 0;
            TotalShots++;
            return 1;
        }
        return 0;
    }
}

public static class StatueCheck
{
    // 프레임 시간이 frameMs 로 일정한 기기에서 totalMs 이상이 지날 때까지 돌렸을 때의 총 발사 수.
    public static int ShotsOver(int frameMs, int totalMs)
    {
        var statue = new LightningStatue(1500);
        for (int t = 0; t < totalMs; t += frameMs) statue.Update(frameMs);
        return statue.TotalShots;
    }
}

