using System;

// 1.5초마다 번개를 쏘는 석상. 가변 dt 루프에서 경과 시간(ms)을 받는다.
// 규칙: 누적 시간이 간격의 배수를 넘을 때마다 한 번씩 쏜다. 한 프레임에 여러 배수를 넘으면 그만큼 쏘고,
//       넘친 시간은 버리지 않고 다음 프레임으로 넘긴다. 그래서 프레임 시간이 달라도 같은 시간에 같은 수를 쏜다.
public sealed class LightningStatue
{
    private readonly int _intervalMs;
    private int _timerMs;   // 마지막 발사 이후 흐른 시간. 항상 0 이상, 간격 미만으로 유지된다.

    public LightningStatue(int intervalMs)
    {
        if (intervalMs <= 0) throw new ArgumentOutOfRangeException(nameof(intervalMs));
        _intervalMs = intervalMs;
    }

    public int TotalShots { get; private set; }

    public int Update(int elapsedMs)
    {
        if (elapsedMs < 0) throw new ArgumentOutOfRangeException(nameof(elapsedMs));
        _timerMs += elapsedMs;
        int shots = 0;
        while (_timerMs >= _intervalMs)     // 렉으로 긴 프레임이 와도 놓친 발사를 모두 처리한다
        {
            _timerMs -= _intervalMs;        // 0 으로 되돌리지 않는다: 넘친 시간을 남긴다
            shots++;
        }
        TotalShots += shots;
        return shots;
    }
}

public static class StatueCheck
{
    public static int ShotsOver(int frameMs, int totalMs)
    {
        var statue = new LightningStatue(1500);
        for (int t = 0; t < totalMs; t += frameMs) statue.Update(frameMs);
        return statue.TotalShots;
    }

    // 16 ms(약 60 FPS), 33 ms(약 30 FPS), 50 ms(20 FPS) 기기에서 60초 동안 모두 40발,
    // 그리고 4초짜리 렉 프레임 한 번에 2발을 쏘고 남은 1초를 넘기는지 확인한다.
    public static bool SameShotsAtAnyFrameRate()
    {
        bool rates = ShotsOver(16, 60000) == 40 && ShotsOver(33, 60000) == 40 && ShotsOver(50, 60000) == 40;
        var statue = new LightningStatue(1500);
        int hitch = statue.Update(4000);    // 4000 = 1500 * 2 + 1000
        int next = statue.Update(500);      // 남은 1000 + 500 = 1500 → 1발
        return rates && hitch == 2 && next == 1 && statue.TotalShots == 3;
    }
}

