using System;
using System.Collections.Generic;

// ----- 완성되어 있습니다. 수정하지 마세요. -----

// 게임 안에 돌아다니는 몬스터 한 마리 (typed object). 몬스터마다 다른 것은 현재 체력뿐이다.
public sealed class Monster
{
    internal Monster(Breed breed)
    {
        Breed = breed;
        Health = breed.MaxHealth;
    }

    public Breed Breed { get; }
    public int Health { get; private set; }

    // 방어력만큼 깎인 피해를 받는다. 체력은 0 아래로 내려가지 않는다.
    public void TakeDamage(int amount)
    {
        int dealt = Math.Max(0, amount - Breed.Armor);
        Health = Math.Max(0, Health - dealt);
    }

    // 몬스터 쪽에서 종족의 값을 덮어쓸 수 있는 자리: 빈사 상태면 다른 문구를 쓴다.
    public string Attack()
    {
        return Health * 4 < Breed.MaxHealth ? Breed.Name + " 이(가) 비틀거리며 허우적댄다" : Breed.AttackText;
    }
}

// ----- 여기부터 구현했습니다. -----

// 몬스터 "종족" 하나 (type object). 만든 뒤에는 바뀌지 않는다.
public sealed class Breed
{
    // 부모 사슬은 Define 이 만든 그 순간에 끝까지 풀어 둔다(copy-down).
    // 종족은 불변이라 나중에 부모가 바뀔 일이 없으므로 결과는 매번 사슬을 걷는 방식과 같다.
    internal Breed(string name, Breed parent, int maxHealth, int armor, string attackText)
    {
        Name = name;
        Parent = parent;
        MaxHealth = maxHealth;
        Armor = armor;
        AttackText = attackText;
    }

    public string Name { get; }
    public Breed Parent { get; }        // 루트 종족이면 null
    public int MaxHealth { get; }
    public int Armor { get; }
    public string AttackText { get; }

    // 이 종족 자신이나 조상 중에 그 이름이 있으면 true. 사슬 깊이만큼 걷는다.
    public bool IsA(string breedName)
    {
        for (Breed b = this; b != null; b = b.Parent)
            if (string.Equals(b.Name, breedName, StringComparison.Ordinal)) return true;
        return false;
    }

    // 몬스터를 만드는 유일한 입구 ("생성자" 역할의 팩터리 메서드).
    public Monster NewMonster()
    {
        return new Monster(this);
    }
}

public sealed class BreedTable
{
    private readonly Dictionary<string, Breed> _breeds = new Dictionary<string, Breed>(StringComparer.Ordinal);

    public int Count
    {
        get { return _breeds.Count; }
    }

    public Breed Define(string name, string parentName, int? maxHealth, int? armor, string attackText)
    {
        // 1) 모든 검사를 먼저 끝낸다. 실패하면 표는 그대로다.
        if (_breeds.ContainsKey(name)) throw new ArgumentException("이미 정의된 종족: " + name, nameof(name));

        Breed parent = null;
        if (parentName != null)
        {
            // 부모는 이미 정의된 것만 쓸 수 있다. 자기 이름을 부모로 주면 아직 없으므로 여기서 걸린다.
            if (!_breeds.TryGetValue(parentName, out parent))
                throw new KeyNotFoundException(name + " 의 부모 종족이 아직 없음: " + parentName);
        }
        else if (maxHealth == null || armor == null || attackText == null)
        {
            throw new ArgumentException("루트 종족은 모든 값을 직접 정해야 함: " + name, nameof(name));
        }

        // 2) null 이면 부모의 (이미 풀린) 값, 아니면 자기 값. 0 과 "" 도 덮어쓰기다.
        var breed = new Breed(
            name,
            parent,
            maxHealth ?? parent.MaxHealth,
            armor ?? parent.Armor,
            attackText ?? parent.AttackText);

        _breeds.Add(name, breed);
        return breed;
    }

    public Breed Get(string name)
    {
        Breed breed;
        if (!_breeds.TryGetValue(name, out breed)) throw new KeyNotFoundException("정의되지 않은 종족: " + name);
        return breed;
    }
}

