public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static System.Exception Thrown(System.Action a)
    {
        try { a(); } catch (System.Exception ex) { return ex; }
        return null;
    }

    static string Name(System.Exception e) { return e == null ? "없음" : e.GetType().Name; }

    static string Vals(Breed b) { return b.MaxHealth + "/" + b.Armor + "/\"" + b.AttackText + "\""; }

    static BreedTable Trolls()
    {
        var t = new BreedTable();
        t.Define("Troll", null, 48, 2, "clubs");
        t.Define("TrollArcher", "Troll", null, null, "arrow");
        t.Define("TrollArcherCaptain", "TrollArcher", 80, null, null);
        t.Define("TrollBrute", "Troll", null, 5, null);
        t.Define("TrollBruteKing", "TrollBrute", null, null, "roars");
        return t;
    }

    public static void Main()
    {
        Run("root-breed", () =>
        {
            var t = new BreedTable();
            if (t.Count != 0) return "새 표의 Count 는 0 이어야 함";
            Breed troll = t.Define("Troll", null, 48, 2, "clubs");
            if (troll == null || troll.Name != "Troll" || troll.Parent != null) return "루트 종족: Name 은 \"Troll\", Parent 는 null 이어야 함";
            if (Vals(troll) != "48/2/\"clubs\"") return "루트 종족 값: 기대 48/2/\"clubs\", 결과 " + Vals(troll);
            if (!ReferenceEquals(t.Get("Troll"), troll) || !ReferenceEquals(t.Get("Troll"), t.Get("Troll"))) return "Get(\"Troll\") 은 Define 이 돌려준 바로 그 객체를 매번 돌려줘야 함";
            if (t.Count != 1) return "Count 기대 1, 결과 " + t.Count;
            var other = new BreedTable();
            return other.Count == 0 && Thrown(() => other.Get("Troll")) is System.Collections.Generic.KeyNotFoundException ? null : "표끼리 종족을 공유하면 안 됨 (static 저장소?)";
        });

        Run("nearest-ancestor-wins", () =>
        {
            var t = Trolls();
            Breed troll = t.Get("Troll"), archer = t.Get("TrollArcher"), captain = t.Get("TrollArcherCaptain"), king = t.Get("TrollBruteKing");
            if (!ReferenceEquals(archer.Parent, troll) || !ReferenceEquals(captain.Parent, archer) || !ReferenceEquals(king.Parent, t.Get("TrollBrute"))) return "Parent 는 Get(부모 이름) 과 같은 객체여야 함";
            if (Vals(archer) != "48/2/\"arrow\"") return "TrollArcher(부모 Troll, null, null, \"arrow\"): 기대 48/2/\"arrow\", 결과 " + Vals(archer);
            if (Vals(captain) != "80/2/\"arrow\"") return "TrollArcherCaptain(부모 TrollArcher, 80, null, null): 기대 80/2/\"arrow\", 결과 " + Vals(captain);
            if (Vals(king) != "48/5/\"roars\"") return "TrollBruteKing(부모 TrollBrute(방어 5), null, null, \"roars\"): 방어력은 가장 가까운 조상의 5, 기대 48/5/\"roars\", 결과 " + Vals(king);
            return Vals(troll) == "48/2/\"clubs\"" ? null : "자식을 정의한 뒤 부모의 값이 바뀜: " + Vals(troll);
        });

        Run("zero-and-empty-override", () =>
        {
            var t = Trolls();
            Breed paper = t.Define("PaperTroll", "TrollBrute", null, 0, "");
            if (Vals(paper) != "48/0/\"\"") return "PaperTroll(부모 TrollBrute, null, 0, \"\"): 0 과 \"\" 도 덮어쓰기, 기대 48/0/\"\", 결과 " + Vals(paper);
            Breed scrap = t.Define("ScrapTroll", "PaperTroll", null, null, null);
            if (Vals(scrap) != "48/0/\"\"") return "ScrapTroll(부모 PaperTroll, 모두 null): 부모의 0 과 \"\" 를 물려받아야 함, 기대 48/0/\"\", 결과 " + Vals(scrap);
            Breed slime = t.Define("Slime", null, 1, 0, "");
            return Vals(slime) == "1/0/\"\"" ? null : "루트 Slime(1, 0, \"\"): 0 과 \"\" 는 값이 주어진 것, 기대 1/0/\"\", 결과 " + Vals(slime);
        });

        Run("define-errors-keep-table", () =>
        {
            var t = Trolls();
            Breed troll = t.Get("Troll");
            System.Exception e = Thrown(() => t.Define("Troll", "TrollArcher", 99, 9, "loop"));
            if (!(e is System.ArgumentException)) return "이미 있는 이름 Troll 을 부모 TrollArcher 로 다시 Define: 기대 ArgumentException, 결과 " + Name(e);
            if (!ReferenceEquals(t.Get("Troll"), troll) || troll.Parent != null || Vals(troll) != "48/2/\"clubs\"") return "실패한 재정의가 기존 Troll 을 바꿈";
            e = Thrown(() => t.Define("Imp", "Imp", 10, 0, "bites"));
            if (!(e is System.Collections.Generic.KeyNotFoundException)) return "자기 자신을 부모로 Define(\"Imp\", \"Imp\", ...): 기대 KeyNotFoundException, 결과 " + Name(e);
            e = Thrown(() => t.Define("Ogre", "Giant", null, null, null));
            if (!(e is System.Collections.Generic.KeyNotFoundException)) return "없는 부모 Giant: 기대 KeyNotFoundException, 결과 " + Name(e);
            e = Thrown(() => t.Define("Ghost", null, 30, null, "wails"));
            if (!(e is System.ArgumentException)) return "루트 Ghost 의 방어력이 null: 기대 ArgumentException, 결과 " + Name(e);
            e = Thrown(() => t.Define("Wisp", null, 30, 1, null));
            if (!(e is System.ArgumentException)) return "루트 Wisp 의 공격 문구가 null: 기대 ArgumentException, 결과 " + Name(e);
            if (t.Count != 5) return "실패한 Define 다섯 번 뒤 Count 기대 5, 결과 " + t.Count;
            foreach (string n in new[] { "Imp", "Ogre", "Ghost", "Wisp", "troll" })
                if (!(Thrown(() => t.Get(n)) is System.Collections.Generic.KeyNotFoundException)) return "Get(\"" + n + "\"): 기대 KeyNotFoundException (실패한 Define 이 등록되었거나 이름 비교가 대소문자를 무시함)";
            Breed ogre = t.Define("Ogre", "Troll", 70, null, null);
            return Vals(ogre) == "70/2/\"clubs\"" && t.Count == 6 ? null : "실패 뒤 같은 이름을 올바르게 Define: 기대 70/2/\"clubs\" 와 Count 6, 결과 " + Vals(ogre) + " / " + t.Count;
        });

        Run("is-a-chain", () =>
        {
            var t = Trolls();
            Breed captain = t.Get("TrollArcherCaptain"), troll = t.Get("Troll"), brute = t.Get("TrollBrute");
            if (!captain.IsA("TrollArcherCaptain") || !captain.IsA("TrollArcher") || !captain.IsA("Troll")) return "TrollArcherCaptain 은 자신, TrollArcher, Troll 모두에 대해 IsA 가 true 여야 함";
            if (troll.IsA("TrollArcher")) return "Troll.IsA(\"TrollArcher\") 는 false (부모가 자식인 것은 아님)";
            if (brute.IsA("TrollArcher") || brute.IsA("TrollArcherCaptain")) return "형제 종족 TrollBrute.IsA(\"TrollArcher\") 는 false";
            if (captain.IsA("troll") || captain.IsA("Dragon")) return "IsA 는 대소문자를 구분하고, 없는 이름이면 false";
            return null;
        });

        Run("monsters-share-breed", () =>
        {
            var t = Trolls();
            Breed captain = t.Get("TrollArcherCaptain");
            Monster a = captain.NewMonster(), b = captain.NewMonster();
            if (a == null || ReferenceEquals(a, b)) return "NewMonster 는 호출할 때마다 새 몬스터를 만들어야 함";
            if (!ReferenceEquals(a.Breed, captain) || !ReferenceEquals(b.Breed, captain)) return "몬스터의 Breed 는 NewMonster 를 부른 종족 객체 그 자체여야 함";
            if (a.Health != 80 || a.Attack() != "arrow") return "새 몬스터: 기대 체력 80 / 공격 \"arrow\", 결과 " + a.Health + " / " + a.Attack();
            a.TakeDamage(12);
            if (a.Health != 70 || b.Health != 80) return "a 만 12 피해(방어 2): 기대 a 70 / b 80, 결과 " + a.Health + " / " + b.Health;
            Monster p = t.Define("PaperTroll", "Troll", null, 0, null).NewMonster();
            p.TakeDamage(5);
            return p.Health == 43 && captain.MaxHealth == 80 ? null : "PaperTroll(방어 0) 이 5 피해: 기대 43, 결과 " + p.Health;
        });

        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(4471);
            for (int round = 0; round < 300; round++)
            {
                var t = new BreedTable();
                var names = new System.Collections.Generic.List<string>();
                var parent = new System.Collections.Generic.List<int>();
                var spec = new System.Collections.Generic.List<object[]>();
                int ops = rng.Next(1, 16);
                for (int op = 0; op < ops; op++)
                {
                    string name = "B" + rng.Next(0, 12);
                    int p = names.Count == 0 || rng.Next(4) == 0 ? -1 : rng.Next(names.Count);
                    bool badParent = rng.Next(10) == 0;
                    string parentName = badParent ? "X" + rng.Next(5) : p < 0 ? null : names[p];
                    int? hp = p < 0 || rng.Next(2) == 0 ? rng.Next(0, 4) * 10 : (int?)null;
                    int? ar = p < 0 || rng.Next(2) == 0 ? rng.Next(0, 3) : (int?)null;
                    string at = p < 0 || rng.Next(2) == 0 ? (rng.Next(3) == 0 ? "" : "a" + rng.Next(5)) : null;
                    if (p < 0 && !badParent && rng.Next(8) == 0) ar = null;
                    bool ok = !names.Contains(name) && !badParent && (p >= 0 || (hp != null && ar != null && at != null));
                    System.Exception e = Thrown(() => t.Define(name, parentName, hp, ar, at));
                    if (ok != (e == null)) return "라운드 " + round + ": Define(" + name + ", " + (parentName ?? "null") + ", ...) " + (ok ? "은 성공해야 함, 결과 " + Name(e) : "은 실패해야 함");
                    if (ok) { names.Add(name); parent.Add(badParent ? -1 : p); spec.Add(new object[] { hp, ar, at }); }
                }
                if (t.Count != names.Count) return "라운드 " + round + ": Count 기대 " + names.Count + ", 결과 " + t.Count;
                for (int i = 0; i < names.Count; i++)
                {
                    object[] want = new object[3];
                    for (int k = 0; k < 3; k++) for (int j = i; want[k] == null; j = parent[j]) want[k] = spec[j][k];
                    Breed b = t.Get(names[i]);
                    string exp = want[0] + "/" + want[1] + "/\"" + want[2] + "\"";
                    if (Vals(b) != exp) return "라운드 " + round + ": " + names[i] + " 기대 " + exp + ", 결과 " + Vals(b);
                    if (!ReferenceEquals(b.Parent, parent[i] < 0 ? null : t.Get(names[parent[i]]))) return "라운드 " + round + ": " + names[i] + " 의 Parent 가 다름";
                    int q = rng.Next(names.Count);
                    bool isA = false;
                    for (int j = i; j >= 0 && !isA; j = parent[j]) isA = j == q;
                    if (b.IsA(names[q]) != isA) return "라운드 " + round + ": " + names[i] + ".IsA(" + names[q] + ") 기대 " + isA;
                }
            }
            return null;
        });
    }
}

