using System;

// 효과음 재생 요청을 받아 두었다가 오디오 쪽의 Update 에서 처리하는 큐.
// 요청하는 쪽(전투, UI, AI)과 재생하는 쪽(오디오)을 "시간"으로 떼어 놓는다.
public sealed class SoundRequestQueue
{
    // 링 버퍼: 생성자에서 한 번 만든 배열 두 개를 끝까지 다시 쓴다.
    private readonly int[] _ids;
    private readonly int[] _volumes;
    private readonly Action<int, int> _play;
    private int _head;    // 가장 오래된 대기 요청이 있는 칸
    private int _count;   // 대기 요청 수. 개수를 따로 두므로 Capacity 칸을 모두 쓴다.

    public SoundRequestQueue(int capacity, Action<int, int> play)
    {
        if (capacity < 1) throw new ArgumentOutOfRangeException(nameof(capacity));
        if (play == null) throw new ArgumentNullException(nameof(play));
        _ids = new int[capacity];
        _volumes = new int[capacity];
        _play = play;
    }

    public int Capacity
    {
        get { return _ids.Length; }
    }

    public int Count
    {
        get { return _count; }
    }

    public int DroppedCount { get; private set; }

    public bool Request(int soundId, int volume)
    {
        if (volume < 0 || volume > 100) throw new ArgumentOutOfRangeException(nameof(volume));

        // 1) 같은 소리가 아직 대기 중이면 그 요청에 합친다. 자리는 그대로, 음량은 큰 쪽.
        //    가득 찬 큐에서도 합치기는 칸을 쓰지 않으므로 받아들인다.
        for (int k = 0, i = _head; k < _count; k++, i = Next(i))
        {
            if (_ids[i] == soundId)
            {
                if (volume > _volumes[i]) _volumes[i] = volume;
                return true;
            }
        }

        // 2) 합칠 곳이 없고 가득 찼으면 새 요청을 버린다.
        if (_count == _ids.Length)
        {
            DroppedCount++;
            return false;
        }

        // 3) 꼬리(가장 오래된 것에서 _count 칸 뒤)에 넣는다.
        int tail = _head + _count;
        if (tail >= _ids.Length) tail -= _ids.Length;
        _ids[tail] = soundId;
        _volumes[tail] = volume;
        _count++;
        return true;
    }

    public int Update(int budget)
    {
        if (budget < 0) throw new ArgumentOutOfRangeException(nameof(budget));

        // 이번 Update 가 처리할 개수는 시작할 때 정한다. 콜백 안에서 들어온 요청은 모두 이들 뒤에 서므로
        // 이번 프레임에는 처리되지 않는다.
        int n = Math.Min(budget, _count);
        for (int k = 0; k < n; k++)
        {
            int id = _ids[_head];
            int volume = _volumes[_head];

            // 콜백을 부르기 전에 큐에서 뺀다. 콜백이 같은 소리를 다시 요청하면 새 요청으로 줄을 서고,
            // 콜백이 예외를 던져도 이 요청이 다시 재생되지 않는다.
            _head = Next(_head);
            _count--;

            _play(id, volume);
        }
        return n;
    }

    private int Next(int i)
    {
        i++;
        return i == _ids.Length ? 0 : i;
    }
}

