            if (t != "InvalidOperationException") return "콜백의 예외는 Update 밖으로 그대로 나와야 함, 결과 " + t;
            string got = Take(log);
            if (got != "11:50 13:50") return "던지기 전까지의 재생 기대 [11:50 13:50] (거절된 Request(11, 101) 은 합쳐지지 않음), 결과 [" + got + "]";
            if (q.Count != 1) return "13 의 콜백이 던진 뒤 Count 기대 1 (11, 13 은 이미 빠짐), 결과 " + q.Count;
