        {
            var rng = new System.Random(90210);
            for (int round = 0; round < 300; round++)
            {
                int cap = rng.Next(1, 7);
                int[] reactId = new int[8], reactVol = new int[8];
                for (int i = 0; i < 8; i++) { reactId[i] = rng.Next(3) == 0 ? rng.Next(8) : -1; reactVol[i] = rng.Next(0, 101); }
                var log = new System.Collections.Generic.List<string>();
                var refLog = new System.Collections.Generic.List<string>();
                SoundRequestQueue q = null;
                q = new SoundRequestQueue(cap, (id, v) => { log.Add(id + ":" + v); if (reactId[id] >= 0) log.Add("r" + q.Request(reactId[id], reactVol[id])); });
                var pend = new System.Collections.Generic.List<int[]>();
                int dropped = 0;
                System.Func<int, int, bool> refReq = (id, v) =>
                {
                    foreach (int[] p in pend) if (p[0] == id) { p[1] = System.Math.Max(p[1], v); return true; }
                    if (pend.Count == cap) { dropped++; return false; }
                    pend.Add(new[] { id, v }); return true;
                };
                for (int op = 0; op < 40; op++)
                {
                    string what;
                    if (rng.Next(3) > 0)
                    {
                        int id = rng.Next(8), v = rng.Next(0, 101);
                        what = "Request(" + id + ", " + v + ")";
                        bool got = q.Request(id, v), exp = refReq(id, v);
                        if (got != exp) return "라운드 " + round + " (Capacity " + cap + "), " + what + ": 기대 " + exp + ", 결과 " + got;
                    }
                    else
                    {
                        int b = rng.Next(0, 4);
                        what = "Update(" + b + ")";
                        int got = q.Update(b), exp = System.Math.Min(b, pend.Count);
                        for (int k = 0; k < exp; k++)
                        {
                            int[] p = pend[0]; pend.RemoveAt(0);
                            refLog.Add(p[0] + ":" + p[1]);
                            if (reactId[p[0]] >= 0) refLog.Add("r" + refReq(reactId[p[0]], reactVol[p[0]]));
                        }
                        string a = Take(log), e = Take(refLog);
                        if (got != exp || a != e) return "라운드 " + round + " (Capacity " + cap + "), " + what + ": 기대 반환 " + exp + " / [" + e + "], 결과 " + got + " / [" + a + "]";
                    }
                    if (q.Count != pend.Count || q.DroppedCount != dropped) return "라운드 " + round + ", " + what + " 뒤: 기대 Count " + pend.Count + " / DroppedCount " + dropped + ", 결과 " + q.Count + " / " + q.DroppedCount;
                }
            }
            return null;
        });

        Run("no-allocation-steady-state", () =>
        {
            long sum = 0;
            var q = new SoundRequestQueue(64, (id, v) => { sum += id * v; });
            System.Action frames = () =>
            {
                for (int f = 0; f < 2000; f++)
                {
                    for (int i = 0; i < 12; i++) q.Request((f * 7 + i * 3) % 40, (f + i) % 101);
                    q.Update(9);
                }
            };
            frames(); frames();
            long before = System.GC.GetAllocatedBytesForCurrentThread();
            frames();
            long bytes = System.GC.GetAllocatedBytesForCurrentThread() - before;
            if (sum == 0) return "콜백이 한 번도 불리지 않음";
            return bytes < 16000 ? null : "준비가 끝난 뒤 2,000 프레임(요청 24,000번)에서 " + bytes + " 바이트를 할당함 (요청이나 Update 마다 힙 할당?)";
        });
    }
}

problems.starterCode:
using System;
using System.Collections.Generic;

// 층 입구 체크포인트 (memento). 세이브 시스템은 Version 만 읽고 나머지는 열어 보지 않는다.
public sealed class PlayerCheckpoint
{
    public const int CurrentVersion = 2;   // v1: 스킬 3개, v2(1.1 패치): 스킬 4개

    public int Version { get; }
    internal readonly int Hp;
    internal readonly int Gold;
    internal readonly List<string> Items;
    internal readonly int[] SkillLevels;

    // 세이브 파일 로더가 쓰는 생성자. 넘겨받은 배열은 복사해서 갖는다.
    public PlayerCheckpoint(int version, int hp, int gold, string[] items, int[] skillLevels)
        : this(version, hp, gold, new List<string>(items), (int[])skillLevels.Clone())
    {
    }

    // PlayerState.Capture 가 쓰는 생성자. 넘겨받은 것을 그대로 갖는다.
    internal PlayerCheckpoint(int version, int hp, int gold, List<string> items, int[] skillLevels)
    {
        Version = version;
        Hp = hp;
        Gold = gold;
        Items = items;
        SkillLevels = skillLevels;
    }
}

// 플레이어 상태 (originator).
public sealed class PlayerState
{
    public const int SkillCount = 4;

    private int _hp = 100;
    private int _gold;
    private List<string> _items = new List<string>();
    private int[] _skillLevels = new int[SkillCount];

    public int Hp
    {
        get { return _hp; }
    }

    public int Gold
    {
        get { return _gold; }
    }

    public IReadOnlyList<string> Items
    {
        get { return _items; }
    }

    public int GetSkillLevel(int skill)
    {
        return _skillLevels[skill];
    }

    public void TakeDamage(int amount)
    {
        _hp = Math.Max(0, _hp - amount);
    }

    public void AddGold(int amount)
    {
        _gold += amount;
    }

    public void AddItem(string itemId)
    {
        _items.Add(itemId);
    }

    public bool RemoveItem(string itemId)
    {
        return _items.Remove(itemId);
    }

    public void LevelUp(int skill)
    {
        _skillLevels[skill]++;
    }

    // 층에 들어설 때 부른다.
    public PlayerCheckpoint Capture()
    {
        return new PlayerCheckpoint(PlayerCheckpoint.CurrentVersion, _hp, _gold, _items, (int[])_skillLevels.Clone());
    }

    // 죽었을 때나 세이브를 불러올 때 부른다.
    public void Restore(PlayerCheckpoint checkpoint)
    {
        if (checkpoint == null) throw new ArgumentNullException(nameof(checkpoint));

        _hp = checkpoint.Hp;
        _gold = checkpoint.Gold;
        _items = new List<string>(checkpoint.Items);
        _skillLevels = checkpoint.SkillLevels;
    }
}

