using System;
using System.Collections.Generic;

// 층 입구 체크포인트 (memento). 세이브 시스템은 Version 만 읽고 나머지는 열어 보지 않는다.
public sealed class PlayerCheckpoint
{
    public const int CurrentVersion = 2;   // v1: 스킬 3개, v2(1.1 패치): 스킬 4개

    public int Version { get; }
    internal readonly int Hp;
    internal readonly int Gold;
    internal readonly List<string> Items;
    internal readonly int[] SkillLevels;

    // 세이브 파일 로더가 쓰는 생성자. 넘겨받은 배열은 복사해서 갖는다.
    public PlayerCheckpoint(int version, int hp, int gold, string[] items, int[] skillLevels)
        : this(version, hp, gold, new List<string>(items), (int[])skillLevels.Clone())
    {
    }

    // PlayerState.Capture 가 쓰는 생성자. 넘겨받은 것을 그대로 갖는다(소유권을 넘겨받는다).
    // 그러니 부르는 쪽은 다른 누구도 갖고 있지 않은 새 컬렉션을 넘겨야 한다.
    internal PlayerCheckpoint(int version, int hp, int gold, List<string> items, int[] skillLevels)
    {
        Version = version;
        Hp = hp;
        Gold = gold;
        Items = items;
        SkillLevels = skillLevels;
    }
}

// 플레이어 상태 (originator).
public sealed class PlayerState
{
    public const int SkillCount = 4;

    private int _hp = 100;
    private int _gold;
    private List<string> _items = new List<string>();
    private int[] _skillLevels = new int[SkillCount];

    public int Hp
    {
        get { return _hp; }
    }

    public int Gold
    {
        get { return _gold; }
    }

    public IReadOnlyList<string> Items
    {
        get { return _items; }
    }

    public int GetSkillLevel(int skill)
    {
        return _skillLevels[skill];
    }

    public void TakeDamage(int amount)
    {
        _hp = Math.Max(0, _hp - amount);
    }

    public void AddGold(int amount)
    {
        _gold += amount;
    }

    public void AddItem(string itemId)
    {
        _items.Add(itemId);
    }

    public bool RemoveItem(string itemId)
    {
        return _items.Remove(itemId);
    }

    public void LevelUp(int skill)
    {
        _skillLevels[skill]++;
    }

    // 층에 들어설 때 부른다.
    public PlayerCheckpoint Capture()
    {
        // 수정 1: 아이템 목록도 복사한다. 그대로 넘기면 체크포인트가 살아 있는 목록을 함께 쓴다.
        return new PlayerCheckpoint(PlayerCheckpoint.CurrentVersion, _hp, _gold,
            new List<string>(_items), (int[])_skillLevels.Clone());
    }

    // 죽었을 때나 세이브를 불러올 때 부른다.
    public void Restore(PlayerCheckpoint checkpoint)
    {
        if (checkpoint == null) throw new ArgumentNullException(nameof(checkpoint));

        // 수정 3: 상태를 건드리기 전에 버전부터 확인하고, 새 스킬 배열을 먼저 완성한다.
        int[] levels = new int[SkillCount];
        if (checkpoint.Version == PlayerCheckpoint.CurrentVersion)
        {
            Array.Copy(checkpoint.SkillLevels, levels, SkillCount);
        }
        else if (checkpoint.Version == 1)
        {
            // v1 에는 네 번째 스킬이 없었다: 앞의 셋을 옮기고 네 번째는 0 으로 둔다.
            Array.Copy(checkpoint.SkillLevels, levels, 3);
        }
        else
        {
            throw new ArgumentException("지원하지 않는 체크포인트 버전: " + checkpoint.Version, nameof(checkpoint));
        }

        _hp = checkpoint.Hp;
        _gold = checkpoint.Gold;
        _items = new List<string>(checkpoint.Items);
        // 수정 2: 체크포인트의 배열을 그대로 가져오지 않는다. 위에서 만든 새 배열을 쓴다.
        _skillLevels = levels;
    }
}

