using System;
using System.Collections.Generic;

// ----- 완성되어 있습니다. 수정하지 마세요. -----

// 전투 코드가 직접 고치는 가변 객체.
public sealed class Unit
{
    public Unit(string name, int hp)
    {
        Name = name;
        Hp = hp;
    }

    public string Name { get; }
    public int Hp { get; set; }
    public List<string> Statuses { get; } = new List<string>();   // "poison", "stun" ...
}

// ----- 여기부터 구현했습니다. -----

// 턴제 전투의 상태 (originator).
public sealed class BattleState
{
    private uint _rng;

    public BattleState(uint seed)
    {
        _rng = seed;
    }

    public int Turn { get; private set; }
    public List<Unit> Units { get; } = new List<Unit>();
    public uint RngState
    {
        get { return _rng; }   // 디버그 표시용
    }

    public void EndTurn()
    {
        Turn++;
    }

    // 명중·치명타 판정에 쓰는 결정적 난수. 호출할 때마다 상태가 바뀐다.
    public int NextRoll(int max)
    {
        _rng = _rng * 1664525u + 1013904223u;
        return (int)((_rng >> 16) % (uint)max);
    }

    public BattleSnapshot Save()
    {
        // 살아 있는 Unit 이나 List 를 하나도 넘기지 않는다. 값만 새 배열로 옮긴다.
        var units = new BattleSnapshot.UnitData[Units.Count];
        for (int i = 0; i < units.Length; i++)
        {
            Unit u = Units[i];
            units[i] = new BattleSnapshot.UnitData(u.Name, u.Hp, u.Statuses.ToArray());
        }
        return new BattleSnapshot(Turn, _rng, units);   // 난수 상태도 상태다
    }

    public void Load(BattleSnapshot snapshot)
    {
        if (snapshot == null) throw new ArgumentNullException(nameof(snapshot));

        // 스냅숏의 배열을 넘기지 않고, 그 값으로 새 Unit 과 새 List 를 만든다.
        // 그래서 Load 뒤에 전투가 무엇을 바꿔도 스냅숏은 그대로이고, 같은 스냅숏을 몇 번이든 다시 쓸 수 있다.
        Units.Clear();
        foreach (BattleSnapshot.UnitData d in snapshot.Units)
        {
            var u = new Unit(d.Name, d.Hp);
            u.Statuses.AddRange(d.Statuses);   // 원소(string)를 복사해 넣는다. 배열은 공유하지 않는다
            Units.Add(u);
        }
        Turn = snapshot.Turn;
        _rng = snapshot.Rng;
    }
}

// 스냅숏 (memento). 바깥에는 Turn 만 보이고, 만든 뒤에는 바뀌지 않는다.
public sealed class BattleSnapshot
{
    internal readonly struct UnitData
    {
        public readonly string Name;
        public readonly int Hp;
        public readonly string[] Statuses;   // 이 스냅숏만 가진 배열. 밖으로 내보내지 않는다

        public UnitData(string name, int hp, string[] statuses)
        {
            Name = name; Hp = hp; Statuses = statuses;
        }
    }

    internal readonly uint Rng;
    internal readonly UnitData[] Units;

    internal BattleSnapshot(int turn, uint rng, UnitData[] units)
    {
        Turn = turn;
        Rng = rng;
        Units = units;
    }

    public int Turn { get; }
}

// 되돌리기 기록 (caretaker). 스냅숏의 내용은 모르고 쌓았다가 돌려줄 뿐이다.
public sealed class TurnHistory
{
    private readonly BattleState _battle;
    private readonly Stack<BattleSnapshot> _checkpoints = new Stack<BattleSnapshot>();

    public TurnHistory(BattleState battle)
    {
        if (battle == null) throw new ArgumentNullException(nameof(battle));
        _battle = battle;
    }

    public int Count
    {
        get { return _checkpoints.Count; }
    }

    public void Checkpoint()
    {
        _checkpoints.Push(_battle.Save());
    }

    public void Undo()
    {
        if (_checkpoints.Count == 0) throw new InvalidOperationException("되돌릴 체크포인트가 없음");
        _battle.Load(_checkpoints.Pop());
    }
}

