public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static string Thrown(System.Action a)
    {
        try { a(); } catch (System.Exception ex) { return ex.GetType().Name; }
        return "없음";
    }

    // "T턴 R난수상태 | 이름:체력[상태,...] ..."
    static string Show(BattleState b)
    {
        var sb = new System.Text.StringBuilder();
        sb.Append("T" + b.Turn + " R" + b.RngState + " |");
        foreach (Unit u in b.Units) sb.Append(" " + u.Name + ":" + u.Hp + "[" + string.Join(",", u.Statuses) + "]");
        return sb.ToString();
    }

    static BattleState Sample()
    {
        var b = new BattleState(12345u);
        var knight = new Unit("knight", 40); knight.Statuses.Add("guard");
        var slime = new Unit("slime", 12); slime.Statuses.Add("poison"); slime.Statuses.Add("slow");
        b.Units.Add(knight); b.Units.Add(slime);
        b.EndTurn(); b.NextRoll(100);
        return b;
    }

    public static void Main()
    {
        Run("snapshot-isolated-from-battle", () =>
        {
            BattleState b = Sample();
            string saved = Show(b);
            BattleSnapshot s = b.Save();
            if (s == null || s.Turn != 1) return "Save 의 Turn 기대 1";
            b.Units[0].Hp -= 15; b.Units[0].Statuses.Add("burn"); b.Units[1].Statuses.Clear();
            b.Units.Add(new Unit("orc", 30)); b.Units.RemoveAt(0);
            b.EndTurn(); b.NextRoll(6); b.NextRoll(6);
            b.Load(s);
            string got = Show(b);
            return got == saved ? null : "Save 뒤 체력·상태·유닛 목록·턴·난수를 바꾸고 Load: 기대 " + saved + ", 결과 " + got;
        });

        Run("load-twice-and-shared-snapshot", () =>
        {
            BattleState b = Sample();
            string saved = Show(b);
            BattleSnapshot s = b.Save();
            b.Load(s);
            b.Units[1].Hp = 0; b.Units[1].Statuses.Add("dead"); b.Units[0].Statuses.Remove("guard");
            b.Load(s);
            string got = Show(b);
            if (got != saved) return "Load → 유닛 변경 → 같은 스냅숏으로 다시 Load: 기대 " + saved + ", 결과 " + got;
            var viewer = new BattleState(1u);
            viewer.Load(s);
            viewer.Units[0].Hp = 1; viewer.Units[0].Statuses.Add("viewer-only");
            got = Show(b);
            if (got != saved) return "다른 전투가 같은 스냅숏을 Load 해 바꾼 값이 원래 전투에 보임: " + got;
            b.Load(s);
            got = Show(b);
            return got == saved ? null : "다른 전투의 변경이 스냅숏을 바꿈: 기대 " + saved + ", 결과 " + got;
        });

        Run("rng-state-restored", () =>
        {
            BattleState b = Sample();
            BattleSnapshot s = b.Save();
            string first = b.NextRoll(100) + "," + b.NextRoll(100) + "," + b.NextRoll(6);
            b.Load(s);
            string second = b.NextRoll(100) + "," + b.NextRoll(100) + "," + b.NextRoll(6);
            if (first != second) return "Save → 판정 3번 → Load → 판정 3번: 같은 수열이어야 함, 기대 " + first + ", 결과 " + second;
            return b.Turn == 1 ? null : "Load 뒤 Turn 기대 1, 결과 " + b.Turn;
        });

        Run("load-null-and-empty", () =>
        {
            var b = new BattleState(7u);
            BattleSnapshot empty = b.Save();
            if (empty.Turn != 0) return "빈 전투의 스냅숏 Turn 기대 0";
            string t = Thrown(() => b.Load(null));
            if (t != "ArgumentNullException") return "Load(null): 기대 ArgumentNullException, 결과 " + t;
            b.Units.Add(new Unit("bat", 5)); b.EndTurn(); b.EndTurn(); b.NextRoll(10);
            b.Load(empty);
            string got = Show(b);
            return got == "T0 R7 |" ? null : "빈 스냅숏으로 Load: 기대 \"T0 R7 |\", 결과 \"" + got + "\"";
        });

        Run("history-undo-stack", () =>
        {
            if (Thrown(() => new TurnHistory(null)) != "ArgumentNullException") return "TurnHistory(null): 기대 ArgumentNullException";
            BattleState b = Sample();
            var h = new TurnHistory(b);
            string s0 = Show(b);
            h.Checkpoint();
            b.Units[1].Hp -= 5; b.Units[1].Statuses.Add("stun"); b.NextRoll(100); b.EndTurn();
            string s1 = Show(b);
            h.Checkpoint();
            b.Units.RemoveAt(1); b.Units[0].Statuses.Add("rage"); b.NextRoll(100); b.EndTurn();
            if (h.Count != 2) return "체크포인트 두 번 뒤 Count 기대 2, 결과 " + h.Count;
            h.Undo();
            if (Show(b) != s1 || h.Count != 1) return "첫 Undo: 기대 " + s1 + " / Count 1, 결과 " + Show(b) + " / " + h.Count;
            b.Units[0].Hp = 99;
            h.Undo();
            if (Show(b) != s0 || h.Count != 0) return "두 번째 Undo: 기대 " + s0 + " / Count 0, 결과 " + Show(b) + " / " + h.Count;
            b.Units[0].Statuses.Add("x");
            string before = Show(b);
            string t = Thrown(() => h.Undo());
            if (t != "InvalidOperationException") return "빈 기록에서 Undo: 기대 InvalidOperationException, 결과 " + t;
            return Show(b) == before ? null : "실패한 Undo 가 전투를 바꿈";
        });

        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(2718);
            string[] st = { "poison", "stun", "guard", "slow" };
            for (int round = 0; round < 200; round++)
            {
                var b = new BattleState((uint)rng.Next());
                var h = new TurnHistory(b);
                var refStack = new System.Collections.Generic.List<string>();
                var snaps = new System.Collections.Generic.List<BattleSnapshot>();
                var snapRefs = new System.Collections.Generic.List<string>();
                for (int op = 0; op < 50; op++)
                {
                    int k = rng.Next(10);
                    if (k == 0) b.Units.Add(new Unit("u" + rng.Next(5), rng.Next(1, 50)));
                    else if (k == 1 && b.Units.Count > 0) b.Units.RemoveAt(rng.Next(b.Units.Count));
                    else if (k == 2 && b.Units.Count > 0) b.Units[rng.Next(b.Units.Count)].Hp -= rng.Next(1, 9);
                    else if (k == 3 && b.Units.Count > 0) b.Units[rng.Next(b.Units.Count)].Statuses.Add(st[rng.Next(4)]);
                    else if (k == 4 && b.Units.Count > 0) b.Units[rng.Next(b.Units.Count)].Statuses.Clear();
                    else if (k == 5) { b.EndTurn(); b.NextRoll(100); }
                    else if (k == 6) { h.Checkpoint(); refStack.Add(Show(b)); }
                    else if (k == 7 && refStack.Count > 0)
                    {
                        h.Undo();
                        string exp = refStack[refStack.Count - 1]; refStack.RemoveAt(refStack.Count - 1);
                        if (Show(b) != exp || h.Count != refStack.Count) return "라운드 " + round + ", 연산 " + op + " Undo: 기대 " + exp + ", 결과 " + Show(b);
                    }
                    else if (k == 8) { snaps.Add(b.Save()); snapRefs.Add(Show(b)); }
                    else if (k == 9 && snaps.Count > 0)
                    {
                        int j = rng.Next(snaps.Count);
                        b.Load(snaps[j]);
                        if (Show(b) != snapRefs[j]) return "라운드 " + round + ", 연산 " + op + ": " + j + " 번째 스냅숏 Load 기대 " + snapRefs[j] + ", 결과 " + Show(b);
                    }
                }
            }
            return null;
        });
    }
}

problems.scenario:
출시 3년 차 온라인 액션 RPG 입니다. 2주마다 패치가 나갑니다. 전투 피해 계산은 `CombatSystem.cs`(4,000줄)의 `ApplyHit` 한 메서드(600줄)에 몰려 있고 테스트는 없습니다. 발췌하면 이렇습니다.

```csharp
public static int ApplyHit(Unit a, Unit t, Skill s)
{
    float d = a.atk * s.pow;
    if (s.type == 3 && t.facing == a.facing) d *= 1.5f;           // 3 = 단검 (배후 공격)
    if (UnityEngine.Random.value < a.crit) { d *= 2f; if (s.type == 3) d *= 1.5f; }
    if (GameManager.Instance.mode == 2) d *= 0.8f;                  // 2 = PvP
    d -= t.def;
    if (d < 1) d = 1;
    t.hp -= (int)d;
    UI.ShowDamage(t, (int)d);
    if (t.hp <= 0) GameManager.Instance.OnKill(a, t);
    return (int)d;
    // ... 이런 분기가 600줄 이어진다
}
```

작년에 누군가 새 브랜치에서 3개월 동안 전투 코드를 통째로 다시 짰지만, 합칠 때 충돌이 쏟아졌고 테스트 서버에서 "피해 숫자가 달라졌다"는 제보가 이어져 버려졌습니다. 이번에는 기획이 "속성 저항" 시스템을 다음 시즌에 넣고 싶어 하고, 그러려면 이 코드를 손봐야 합니다.

리드가 묻습니다.

**"이 레거시 전투 코드를 안전하게 리팩터링하는 계획을 말해 주세요. 무엇부터 테스트로 고정할지(특성 테스트), 새 구현을 어떻게 옆에 키워 옮길지(스트랭글러 피그), 기능 플래그를 어디에 쓰고 언제 지울지, 그리고 이름 짓기와 코드 리뷰를 어떻게 운영할지까지요."**

(시계·난수를 생성자로 주입하는 방법, Humble Object, 테스트 대역의 종류는 다른 문제에서 다뤘습니다. 결합도·응집도 진단도 범위 밖입니다. 여기서는 "동작을 바꾸지 않고 구조를 바꾸는 절차"에 집중합니다.)
